div.script:
//

(function () {
  'use strict';

  var KEY = 'saleen.settings.v2';
  var DEFAULTS = { name: '', accent: '#a78bfa', wallpaper: 'ocean' };
  var ACCENTS = ['#a78bfa', '#c4b5fd', '#8b5cf6', '#d8b4fe', '#f0abfc', '#e879f9', '#fca5a5', '#a3e635'];

  /* Saleen renders every page itself through a remote proxy, so the only thing
     this browser talks to directly is the proxy. No DuckDuckGo, no Bing. */
  var PROXY_RAW = 'https://api.allorigins.win/raw?url=';
  var PROXY_ALT = 'https://api.codetabs.com/v1/proxy/?quest=';
  var PROXY_FAST = 'https://proxy.corsfix.com/?';
  /* Cloudflare Worker proxy. Raw URL goes straight after the slash. */
  var PROXY_CF = 'https://cors.eu.org/';
  /* Two more workers used only when the main one is busy or slow. */
  var PROXY_LOL = 'https://api.cors.lol/?url=';
  var PROXY_ORG = 'https://corsproxy.org/?';
  var JINA = 'https://r.jina.ai/';
  var SEARCH_URL = 'saleen://search?q=';
  var WALLS = [
    { id: 'ocean', label: '🟣 Purple' },
    { id: 'reef', label: '🌸 Violet' },
    { id: 'abyss', label: '🌌 Deep' },
    { id: 'plain', label: '◻ Plain' }
  ];
  var MODE_TITLES = { home: 'Home', browser: 'Home', ai: 'AI', links: 'Links', games: 'Games', movies: 'Movies', tv: 'TV', music: 'Music' };
  var REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var DESKTOP = /[?&]desktop=1/.test(window.location.search);
  var $ = function (sel) { return document.querySelector(sel); };
  /* The same app also ships as a standalone SVG (for esm.sh, which refuses to
     run scripts in .html). An SVG document has no <body>, so everything that
     used to poke at document.body goes through here. */
  function rootNode() {
    return document.body || document.getElementById('saleen-root') || document.documentElement;
  }

  /* In an SVG document document.createElement() builds SVG-namespace elements.
     Those get no HTML layout at all, so every card, poster and cover assembled
     at runtime collapsed into loose text. Point element creation back at the
     XHTML namespace the app is drawn in. */
  var XHTML_NS = 'http://www.w3.org/1999/xhtml';
  var SVG_NS = 'http://www.w3.org/2000/svg';
  if (document.documentElement.namespaceURI === SVG_NS) {
    var nativeCreate = document.createElement.bind(document);
    document.createElement = function (tag) {
      if (/^(svg|g|defs|path|circle|ellipse|rect|line|polyline|polygon|text|tspan|use|clipPath|mask|linearGradient|radialGradient|stop)$/i.test(String(tag))) {
        return nativeCreate(tag);
      }
      return document.createElementNS(XHTML_NS, tag);
    };
  }

  var settings = Object.assign({}, DEFAULTS);
  var mode = 'browser';

  var els = {
    scene: $('#ocean'),
    railTime: $('#railTime'),
    railDate: $('#railDate'),
    tabList: $('#tabList'),
    newTabBtn: $('#newTabBtn'),
    back: $('#backBtn'),
    fwd: $('#fwdBtn'),
    reload: $('#reloadBtn'),
    omni: $('#omni'),
    omniForm: $('#omniForm'),
    chrome: $('#chrome'),
    newTabView: $('#newTabView'),
    startView: $('#startView'),
    heroTime: $('#heroTime'),
    heroGreeting: $('#heroGreeting'),
    heroDate: $('#heroDate'),
    heroSearch: $('#heroSearch'),
    heroInput: $('#heroInput'),
    typingText: $('#typingText'),
    heroTyping: $('#heroTyping'),
    webWrap: $('#webWrap'),
    frame: $('#webFrame'),
    banner: $('#webBanner p'),
    note: $('#webNote'),
    searchPane: $('#searchPane'),
    searchList: $('#searchList'),
    pageLoading: $('#pageLoading'),
    pageLoadingText: $('#pageLoadingText'),
    movieLoad: $('#movieLoad'),
    movieStatus: $('#movieStatus'),
    movieFill: $('#movieFill'),
    movieWrap: $('#movieWrap'),
    readerBtn: $('#readerBtn'),
    readerPane: $('#webReader'),
    webReader: $('#webReader'),
    readerDoc: $('#readerDoc'),
    aiView: $('#aiView'),
    linksView: $('#linksView'),
    gamesView: $('#gamesView'),
    moviesView: $('#moviesView'),
    mediaTitle: $('#mediaTitle'),
    mediaSub: $('#mediaSub'),
    mediaGrid: $('#mediaGrid'),
    mediaFilters: $('#mediaFilters'),
    providerFilters: $('#providerFilters'),
    mediaChips: Array.prototype.slice.call(document.querySelectorAll('#mediaFilters .media-chip')),
    providerChips: Array.prototype.slice.call(document.querySelectorAll('#providerFilters .media-chip')),
    mediaSearch: $('#mediaSearch'),
    mediaBack: $('#mediaBack'),
    seasonSel: $('#seasonSel'),
    episodeSel: $('#episodeSel'),
    linksBody: $('#linksBody'),
    myLinks: $('#myLinks'),
    myLinksCount: $('#myLinksCount'),
    gamesBody: $('#gamesBody'),
    gamesTitle: $('#gamesTitle'),
    gamesSub: $('#gamesSub'),
    gameWrap: $('#gameWrap'),
    gameLoad: $('#gameLoad'),
    gameStatus: $('#gameStatus'),
    gameFill: $('#gameFill'),
    gameGrid: $('#gameGrid'),
    gameSearch: $('#gameSearch'),
    gameBack: $('#gameBack'),
    toast: $('#toast')
  };

  var navItems = Array.prototype.slice.call(document.querySelectorAll('.nav-item'));

  /* ---------------- settings ---------------- */

  function load() {
    try {
      var raw = localStorage.getItem(KEY);
      if (!raw) return;
      var saved = JSON.parse(raw);
      if (!saved || typeof saved !== 'object') return;
      Object.keys(DEFAULTS).forEach(function (k) {
        if (typeof saved[k] === 'string') settings[k] = saved[k];
      });
    } catch (e) { /* ignore corrupt storage */ }
  }

  function save() {
    try { localStorage.setItem(KEY, JSON.stringify(settings)); } catch (e) {}
  }

  function sanitize() {
    var legacy = { stars: 'ocean', aurora: 'reef', mesh: 'reef' };
    if (legacy[settings.wallpaper]) settings.wallpaper = legacy[settings.wallpaper];
    if (!WALLS.some(function (w) { return w.id === settings.wallpaper; })) settings.wallpaper = DEFAULTS.wallpaper;
    if (!/^#[0-9a-f]{6}$/i.test(settings.accent)) settings.accent = DEFAULTS.accent;
    if (settings.name.length > 24) settings.name = settings.name.slice(0, 24);
  }

  function greetingText() {
    var h = new Date().getHours();
    var g = h < 5 ? 'Still up' : h < 12 ? 'Good morning' : h < 18 ? 'Good afternoon' : 'Good evening';
    return settings.name ? g + ', ' + settings.name : g;
  }

  function two(n) {
    return n < 10 ? '0' + n : String(n);
  }

  function updateClock() {
    var now = new Date();
    var time = two(now.getHours()) + ':' + two(now.getMinutes());
    var date = now.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' });
    if (els.railTime) els.railTime.textContent = time;
    if (els.railDate) els.railDate.textContent = date;
    if (els.heroTime) els.heroTime.textContent = time;
    if (els.heroGreeting) els.heroGreeting.textContent = greetingText();
    if (els.heroDate) {
      els.heroDate.textContent = now.toLocaleDateString(undefined, {
        weekday: 'long', month: 'long', day: 'numeric', year: 'numeric'
      });
    }
  }

  /* ---------------- typewriter ---------------- */

  var TYPED_LINES = [
    '- Made by 762.',
    '- saleen still in progress, might be blocked but wtv \uD83D\uDC94'
  ];
  var typeIndex = -1;
  var typePos = 0;
  var typePhase = 'typing';
  var typeTimer = null;

  function pickLine() {
    if (TYPED_LINES.length < 2) return 0;
    var next = typeIndex;
    while (next === typeIndex) {
      next = Math.floor(Math.random() * TYPED_LINES.length);
    }
    return next;
  }

  function typeRender() {
    if (!els.typingText) return;
    els.typingText.textContent = TYPED_LINES[typeIndex].slice(0, typePos);
  }

  function typeStep() {
    if (!els.typingText) return;
    var line = TYPED_LINES[typeIndex];
    var delay = 70;

    if (typePhase === 'typing') {
      typePos += 1;
      typeRender();
      if (typePos >= line.length) {
        typePhase = 'holding';
        delay = 3000;
      }
    } else if (typePhase === 'holding') {
      typePhase = 'deleting';
      delay = 40;
    } else {
      typePos -= 1;
      typeRender();
      delay = 32;
      if (typePos <= 0) {
        typePos = 0;
        typeRender();
        typeIndex = pickLine();
        typePhase = 'typing';
        delay = 600;
      }
    }

    typeTimer = window.setTimeout(typeStep, delay);
  }

  function startTyping() {
    if (!els.typingText) return;
    window.clearTimeout(typeTimer);
    typeIndex = pickLine();
    typePos = 0;
    typePhase = 'typing';
    typeRender();
    typeTimer = window.setTimeout(typeStep, 500);
  }

  function updateTitle() {
    /* The dashboard/disguise tab name: never shows what is really loaded. */
    document.title = 'about:blank';
  }

  function apply() {
    document.documentElement.style.setProperty('--accent', settings.accent);
    rootNode().dataset.wall = settings.wallpaper;
    renderTabs();
    updateTitle();
    startScene();
  }

  function setSetting(key, value) {
    settings[key] = value;
    save();
    apply();
  }

  /* ---------------- ocean scene ---------------- */

  var sctx = els.scene ? els.scene.getContext('2d') : null;
  var bubbles = [];
  var motes = [];
  var W = 0;
  var H = 0;
  var sceneRunning = false;

  function sizeScene() {
    if (!sctx) return;
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth;
    H = window.innerHeight;
    els.scene.width = Math.max(1, Math.floor(W * dpr));
    els.scene.height = Math.max(1, Math.floor(H * dpr));
    sctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    var bubbleCount = Math.max(26, Math.min(96, Math.round(W * H / 22000)));
    bubbles = [];
    for (var i = 0; i < bubbleCount; i++) {
      bubbles.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: 0.9 + Math.random() * Math.random() * 7,
        s: 8 + Math.random() * 22,
        wob: Math.random() * Math.PI * 2,
        wobA: 0.4 + Math.random() * 1.4,
        wobS: 0.006 + Math.random() * 0.014,
        a: 0.18 + Math.random() * 0.34
      });
    }

    var moteCount = Math.max(50, Math.min(180, Math.round(W * H / 12000)));
    motes = [];
    for (var k = 0; k < moteCount; k++) {
      motes.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: 0.3 + Math.random() * 1.1,
        v: 0.06 + Math.random() * 0.22,
        p: Math.random() * Math.PI * 2,
        s: 0.4 + Math.random()
      });
    }
  }

  function paintScene() {
    if (!sctx) return;
    sctx.clearRect(0, 0, W, H);

    /* plankton: tiny lights that twinkle while drifting up */
    for (var m = 0; m < motes.length; m++) {
      var mo = motes[m];
      mo.p += 0.01 * mo.s;
      mo.y -= mo.v;
      mo.x += Math.sin(mo.p * 0.7) * 0.12;
      if (mo.y < -4) { mo.y = H + 4; mo.x = Math.random() * W; }
      sctx.globalAlpha = 0.15 + 0.55 * (0.5 + 0.5 * Math.sin(mo.p));
      sctx.beginPath();
      sctx.arc(mo.x, mo.y, mo.r, 0, Math.PI * 2);
      sctx.fillStyle = '#bdf3ff';
      sctx.fill();
    }

    /* bubbles: rings with a highlight, rising and swaying */
    for (var i = 0; i < bubbles.length; i++) {
      var b = bubbles[i];
      b.wob += b.wobS;
      b.y -= b.s * 0.016;
      b.x += Math.sin(b.wob) * b.wobA * 0.06;
      if (b.y < -20) {
        b.y = H + 20 + Math.random() * 60;
        b.x = Math.random() * W;
      }

      sctx.globalAlpha = b.a;
      sctx.beginPath();
      sctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      sctx.strokeStyle = 'rgba(198,246,255,0.85)';
      sctx.lineWidth = 1;
      sctx.stroke();

      if (b.r > 2) {
        sctx.globalAlpha = b.a * 0.9;
        sctx.beginPath();
        sctx.arc(b.x - b.r * 0.34, b.y - b.r * 0.34, Math.max(0.6, b.r * 0.2), 0, Math.PI * 2);
        sctx.fillStyle = '#ffffff';
        sctx.fill();
      }
    }

    sctx.globalAlpha = 1;
  }

  function stopScene() {
    sceneRunning = false;
    if (!sctx) return;
    sctx.clearRect(0, 0, W, H);
  }

  function startScene() {
    if (!sctx) return;
    if (settings.wallpaper === 'plain') { stopScene(); return; }
    if (!bubbles.length) sizeScene();
    if (sceneRunning) return;
    sceneRunning = true;
    var tick = function () {
      if (!sceneRunning) return;
      paintScene();
      window.requestAnimationFrame(tick);
    };
    window.requestAnimationFrame(tick);
  }

  /* ---------------- live wallpaper ---------------- */

  var wall = document.getElementById('wall');
  var parX = 0, parY = 0, parTX = 0, parTY = 0, parQueued = false;

  function parStep() {
    parX += (parTX - parX) * 0.14;
    parY += (parTY - parY) * 0.14;
    var done = Math.abs(parTX - parX) < 0.1 && Math.abs(parTY - parY) < 0.1;
    if (done) { parX = parTX; parY = parTY; }
    wall.style.setProperty('--px', parX.toFixed(2) + 'px');
    wall.style.setProperty('--py', parY.toFixed(2) + 'px');
    if (done) { parQueued = false; return; }
    window.requestAnimationFrame(parStep);
  }

  function parQueue() {
    if (parQueued) return;
    parQueued = true;
    window.requestAnimationFrame(parStep);
  }

  function parMove(e) {
    if (REDUCED) return;
    var nx = (e.clientX / Math.max(1, window.innerWidth) - 0.5) * 2;
    var ny = (e.clientY / Math.max(1, window.innerHeight) - 0.5) * 2;
    parTX = -nx * 16;
    parTY = -ny * 16;
    parQueue();
  }

  function parReset() {
    if (REDUCED) return;
    parTX = 0;
    parTY = 0;
    parQueue();
  }

  window.addEventListener('pointermove', parMove, { passive: true });
  window.addEventListener('blur', parReset);
  document.addEventListener('pointerleave', parReset);

  /* ---------------- tabs ---------------- */

  var tabs = [];
  var activeId = null;
  var seq = 0;

  function activeTab() {
    for (var i = 0; i < tabs.length; i++) if (tabs[i].id === activeId) return tabs[i];
    return null;
  }

  function createTab() {
    var t = { id: 't' + (++seq), title: '', url: '', mode: 'new', hist: [], hi: -1 };
    tabs.push(t);
    activeId = t.id;
    renderTabs();
    renderView();
    return t;
  }

  function selectTab(id) {
    if (activeId === id && mode === 'browser') return;
    activeId = id;
    if (mode !== 'browser') {
      mode = 'browser';
      document.dispatchEvent(new CustomEvent('saleen:mode', { detail: mode }));
    }
    renderTabs();
    renderView();
  }

  function closeTab(id) {
    var i = -1;
    for (var n = 0; n < tabs.length; n++) if (tabs[n].id === id) { i = n; break; }
    if (i < 0) return;
    var wasActive = tabs[i].id === activeId;
    tabs.splice(i, 1);
    if (!tabs.length) {
      activeId = null;
      renderTabs();
      createTab();
      if (mode === 'browser') els.omni.focus();
      return;
    }
    if (wasActive) {
      activeId = (tabs[i] || tabs[i - 1]).id;
      renderTabs();
      renderView();
    } else {
      renderTabs();
    }
  }

  function renderTabs() {
    els.tabList.textContent = '';
    tabs.forEach(function (t) {
      var el = document.createElement('div');
      el.className = 'tab';
      el.setAttribute('role', 'tab');
      el.tabIndex = 0;
      el.setAttribute('aria-selected', t.id === activeId ? 'true' : 'false');

      var ico = document.createElement('span');
      ico.className = 'tab-ico';
      ico.setAttribute('aria-hidden', 'true');
      if (t.mode === 'web' && t.url) {
        ico.textContent = (hostOf(t.url)[0] || '?').toUpperCase();
      } else {
        ico.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 14c2 0 2-2 4-2s2 2 4 2 2-2 4-2 2 2 4 2 2-2 4-2"/><path d="M3 18c2 0 2-2 4-2s2 2 4 2 2-2 4-2 2 2 4 2 2-2 4-2"/></svg>';
        ico.classList.add('wave');
      }

      var title = document.createElement('span');
      title.className = 'tab-title';
      title.textContent = t.title || 'New tab';

      var x = document.createElement('button');
      x.type = 'button';
      x.className = 'tab-x';
      x.textContent = '✕';
      x.title = 'Close tab';
      x.setAttribute('aria-label', 'Close tab');
      x.addEventListener('click', function (e) {
        e.stopPropagation();
        closeTab(t.id);
      });

      el.addEventListener('click', function () { selectTab(t.id); });
      el.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectTab(t.id); }
        if (e.key === 'Delete' || e.key === 'Backspace') { e.preventDefault(); closeTab(t.id); }
      });

      el.appendChild(ico);
      el.appendChild(title);
      el.appendChild(x);
      els.tabList.appendChild(el);
    });
  }

  function hostOf(u) {
    try { return new URL(u).hostname.replace(/^www\./, '') || u; }
    catch (e) { return u; }
  }

  /* ---------------- reader (plain text fallback) ---------------- */

  var readerChoice = {};
  var readerCache = {};
  var readerReq = 0;

  function autoReader(url) {
    /* The proxy renders pages now, so text mode is only ever a manual choice
       (or the automatic fallback when a page cannot be rendered at all). */
    return false;
  }

  function wantsReader(t) {
    if (Object.prototype.hasOwnProperty.call(readerChoice, t.url)) return readerChoice[t.url];
    return autoReader(t.url);
  }

  function setReader(url, on) {
    readerChoice[url] = on;
    if (on) delete readerCache[url];
    renderView();
  }

  function absoluteUrl(href, base) {
    try {
      var u = new URL(href, base);
      if (u.protocol !== 'http:' && u.protocol !== 'https:') return '';
      return u.href;
    } catch (e) { return ''; }
  }

  function linkNode(label, href, doc) {
    var a = doc.createElement('a');
    a.textContent = label;
    a.href = href;
    a.title = href;
    a.addEventListener('click', function (e) {
      e.preventDefault();
      navigate(href);
    });
    return a;
  }

  function inlineNodes(text, baseUrl, doc) {
    var out = [];
    var src = String(text)
      .replace(/\[!\[[^\]]*\]\([^)]*\)\]\([^)]*\)/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '');
    var i = 0;
    var re = /\[([^\][]*)\]\(([^()\s]+)[^)]*\)|\*\*([^*]+)\*\*|`([^`]+)`/g;
    var m;
    while ((m = re.exec(src))) {
      if (m.index > i) out.push(doc.createTextNode(src.slice(i, m.index)));
      if (m[2] !== undefined) {
        var href = absoluteUrl(m[2], baseUrl);
        if (href) out.push(linkNode(m[1] || href, href, doc));
        else out.push(doc.createTextNode(m[1] || m[2]));
      } else if (m[3] !== undefined) {
        var strong = doc.createElement('strong');
        inlineNodes(m[3], baseUrl, doc).forEach(function (n) { strong.appendChild(n); });
        out.push(strong);
      } else if (m[4] !== undefined) {
        var code = doc.createElement('code');
        code.textContent = m[4];
        out.push(code);
      }
      i = re.lastIndex;
    }
    if (i < src.length) out.push(doc.createTextNode(src.slice(i)));
    return out;
  }

  function renderMarkdown(root, md, baseUrl) {
    var doc = document;
    var lines = String(md).split(/\r?\n/);
    var para = [];
    var list = null;
    var i = 0;

    function flushPara() {
      if (!para.length) return;
      var p = doc.createElement('p');
      para.forEach(function (line, idx) {
        if (idx) p.appendChild(doc.createElement('br'));
        inlineNodes(line, baseUrl, doc).forEach(function (n) { p.appendChild(n); });
      });
      root.appendChild(p);
      para = [];
    }

    while (i < lines.length) {
      var line = lines[i];

      if (/^```/.test(line)) {
        flushPara();
        list = null;
        var buf = [];
        i += 1;
        while (i < lines.length && !/^```/.test(lines[i])) { buf.push(lines[i]); i += 1; }
        i += 1;
        var pre = doc.createElement('pre');
        var code = doc.createElement('code');
        code.textContent = buf.join('\n');
        pre.appendChild(code);
        root.appendChild(pre);
        continue;
      }

      if (!line.trim()) {
        flushPara();
        list = null;
        i += 1;
        continue;
      }

      var h = line.match(/^(#{1,4})\s+(.*)$/);
      if (h) {
        flushPara();
        list = null;
        var el = doc.createElement('h' + h[1].length);
        inlineNodes(h[2], baseUrl, doc).forEach(function (n) { el.appendChild(n); });
        root.appendChild(el);
        i += 1;
        continue;
      }

      if (/^\s*([-*_])\s*\1\s*\1\s*$/.test(line)) {
        flushPara();
        list = null;
        i += 1;
        continue;
      }

      var li = line.match(/^\s*(?:[-*+]|\d+\.)\s+(.*)$/);
      if (li) {
        flushPara();
        if (!list) {
          list = doc.createElement('ul');
          root.appendChild(list);
        }
        var item = doc.createElement('li');
        inlineNodes(li[1], baseUrl, doc).forEach(function (n) { item.appendChild(n); });
        list.appendChild(item);
        i += 1;
        continue;
      }

      var bq = line.match(/^>\s?(.*)$/);
      if (bq) {
        flushPara();
        list = null;
        var quote = doc.createElement('blockquote');
        inlineNodes(bq[1], baseUrl, doc).forEach(function (n) { quote.appendChild(n); });
        root.appendChild(quote);
        i += 1;
        continue;
      }

      list = null;
      para.push(line.trim());
      i += 1;
    }
    flushPara();
  }

  function paintReaderError(t, err) {
    els.readerDoc.textContent = '';
    els.readerDoc.dataset.url = t.url;
    var p = document.createElement('p');
    p.className = 'reader-status';
    p.textContent = 'The reader could not load this page' +
      (err && err.message ? ' (' + err.message + ')' : '') + '.';

    var retry = document.createElement('button');
    retry.type = 'button';
    retry.className = 'strip-btn';
    retry.textContent = 'Try again';
    retry.addEventListener('click', function () {
      delete readerCache[t.url];
      els.readerDoc.dataset.url = '';
      renderView();
    });

    var page = document.createElement('button');
    page.type = 'button';
    page.className = 'strip-btn';
    page.textContent = 'Show the page';
    page.addEventListener('click', function () { setReader(t.url, false); });

    p.appendChild(document.createElement('br'));
    p.appendChild(retry);
    p.appendChild(document.createTextNode(' '));
    p.appendChild(page);
    els.readerDoc.appendChild(p);
  }

  function paintReader(t, parsed) {
    els.readerDoc.textContent = '';
    els.readerDoc.dataset.url = t.url;

    var meta = document.createElement('div');
    meta.className = 'reader-meta';
    var host = document.createElement('span');
    host.textContent = hostOf(t.url);
    var dot = document.createElement('span');
    dot.className = 'dotsep';
    dot.textContent = '·';
    var kind = document.createElement('span');
    kind.textContent = 'text view';
    meta.appendChild(host);
    meta.appendChild(dot);
    meta.appendChild(kind);
    els.readerDoc.appendChild(meta);

    renderMarkdown(els.readerDoc, parsed.body, t.url);

    if (!els.readerDoc.textContent.trim()) {
      var empty = document.createElement('p');
      empty.className = 'reader-status';
      empty.textContent = 'The reader returned no text for this page.';
      els.readerDoc.appendChild(empty);
    }

    var title = (parsed.title || '').trim();
    if (title && !/^https?:\/\//i.test(title) && title.length <= 90 && title !== t.title) {
      t.title = title.slice(0, 60);
      renderTabs();
      updateTitle();
    }
  }

  function loadReader(t) {
    var url = t.url;
    if (els.readerDoc.dataset.url === url) return;
    els.readerDoc.dataset.url = url;
    var token = ++readerReq;

    if (readerCache[url]) {
      paintReader(t, readerCache[url]);
      return;
    }

    els.readerDoc.textContent = '';
    var status = document.createElement('p');
    status.className = 'reader-status';
    status.textContent = 'Loading a text version…';
    els.readerDoc.appendChild(status);

    fetchReader(url)
      .then(function (parsed) {
        readerCache[url] = parsed;
        if (token !== readerReq || !stillReading(t, url)) return;
        paintReader(t, parsed);
      })
      .catch(function (err) {
        if (token !== readerReq || !stillReading(t, url)) return;
        readerCache[url] = null;
        paintReaderError(t, err);
      });
  }

  function stillReading(t, url) {
    return mode === 'browser' && activeTab() === t && t.url === url && wantsReader(t);
  }

  function fetchWithTimeout(target, ms, options) {
    var ctrl = window.AbortController ? new AbortController() : null;
    var timer = ctrl ? window.setTimeout(function () { ctrl.abort(); }, ms) : null;
    var opts = Object.assign({}, options || {});
    if (ctrl) opts.signal = ctrl.signal;
    return fetch(target, opts).then(
      function (res) {
        if (timer) window.clearTimeout(timer);
        return res;
      },
      function (err) {
        if (timer) window.clearTimeout(timer);
        throw err;
      }
    );
  }

  function htmlToText(html) {
    var doc = new DOMParser().parseFromString(html, 'text/html');
    Array.prototype.forEach.call(doc.querySelectorAll('script,style,noscript,svg,iframe,template'), function (n) {
      n.parentNode.removeChild(n);
    });
    var out = [];
    Array.prototype.forEach.call(doc.querySelectorAll('h1,h2,h3,h4,p,li,blockquote,pre'), function (el) {
      if (el.querySelector('h1,h2,h3,h4,p,li,blockquote,pre')) return;
      var txt = (el.textContent || '').replace(/\s+/g, ' ').trim();
      if (!txt) return;
      var tag = el.tagName.toLowerCase();
      if (/^h[1-4]$/.test(tag)) out.push(new Array(Number(tag.charAt(1)) + 1).join('#') + ' ' + txt);
      else if (tag === 'li') out.push('- ' + txt);
      else if (tag === 'blockquote') out.push('> ' + txt);
      else out.push(txt);
    });
    if (!out.length && doc.body) {
      var plain = (doc.body.textContent || '').replace(/\s+/g, ' ').trim();
      if (plain) out.push(plain);
    }
    var body = out.join('\n\n');
    if (!body.trim()) throw new Error('no text found');
    return { title: (doc.title || '').trim(), body: body };
  }

  /* r.jina.ai: fastest and cleanest (markdown). Returns 403 for a few "anonymous access"
     domains, so a bare host is retried with www. below. */
  function fromJina(url) {
    return fetchWithTimeout('https://r.jina.ai/' + url, 12000).then(function (res) {
      if (!res.ok) throw new Error('reader returned HTTP ' + res.status);
      return res.text();
    }).then(function (text) {
      var title = '';
      var body = text;
      var titleMatch = text.match(/^Title:\s*(.+)$/m);
      if (titleMatch) title = titleMatch[1].trim();
      var cut = text.indexOf('Markdown Content:');
      if (cut >= 0) body = text.slice(cut + 'Markdown Content:'.length);
      body = body.replace(/^\s*\n/, '');
      if (!body.trim()) throw new Error('empty reader response');
      return { title: title, body: body };
    });
  }

  function withWww(url) {
    try {
      var u = new URL(url);
      if (u.hostname.split('.').length === 2) {
        u.hostname = 'www.' + u.hostname;
        return u.href;
      }
    } catch (e) {}
    return '';
  }

  function fromAllOrigins(url) {
    return fetchWithTimeout('https://api.allorigins.win/get?url=' + encodeURIComponent(url), 12000)
      .then(function (res) {
        if (!res.ok) throw new Error('proxy returned HTTP ' + res.status);
        return res.json();
      })
      .then(function (data) {
        if (!data || !data.contents) throw new Error('empty proxy response');
        return htmlToText(data.contents);
      });
  }

  function fromCodetabs(url) {
    return fetchWithTimeout('https://api.codetabs.com/v1/proxy/?quest=' + encodeURIComponent(url), 12000)
      .then(function (res) {
        if (!res.ok) throw new Error('proxy returned HTTP ' + res.status);
        return res.text();
      })
      .then(function (html) { return htmlToText(html); });
  }

  /* Last resort: Microlink renders the page server-side and returns the body HTML. */
  function fromMicrolink(url) {
    var api = 'https://api.microlink.io/?url=' + encodeURIComponent(url) +
      '&meta=false&data.content.selector=body&data.content.type=html';
    return fetchWithTimeout(api, 15000)
      .then(function (res) {
        if (!res.ok) throw new Error('renderer returned HTTP ' + res.status);
        return res.json();
      })
      .then(function (data) {
        var html = data && data.data && data.data.content;
        if (!html) throw new Error('empty renderer response');
        return htmlToText(html);
      });
  }

  function firstOf(factories) {
    return new Promise(function (resolve, reject) {
      var pending = factories.length;
      var lastErr = null;
      if (!pending) { reject(new Error('nothing to try')); return; }
      factories.forEach(function (make) {
        Promise.resolve().then(make).then(resolve, function (err) {
          lastErr = err;
          pending -= 1;
          if (!pending) reject(lastErr || new Error('all readers failed'));
        });
      });
    });
  }

  function fetchReader(url) {
    var alt = withWww(url);
    return fromJina(url)
      .catch(function () { return alt ? fromJina(alt) : Promise.reject(new Error('no www variant')); })
      .catch(function () { return firstOf([function () { return fromAllOrigins(url); }, function () { return fromCodetabs(url); }]); })
      .catch(function () { return fromMicrolink(url); });
  }

  /* ---------------- Saleen browser ---------------- */

  /* Pages are fetched by a proxy and redrawn by Saleen itself, so a school
     filter that blocks a domain never sees a request to that domain. */
  var pageCache = {};
  var pageReq = 0;
  var searchCache = {};
  var searchReq = 0;
  var proxyHealth = {};

  function cooling(key) {
    return proxyHealth[key] && (Date.now() - proxyHealth[key] < 60000);
  }

  function proxyUrl(target) {
    return PROXY_RAW + encodeURIComponent(target);
  }

  function cfUrl(target) {
    return PROXY_CF + target;
  }

  /* The fastest proxy writes the target URL straight into the query string.
     Encoding it makes the service answer 400, so it gets its own builder. */
  function fastUrl(target) {
    return PROXY_FAST + target;
  }

  function lolUrl(target) {
    return PROXY_LOL + encodeURIComponent(target);
  }

  function orgUrl(target) {
    return PROXY_ORG + encodeURIComponent(target);
  }

  /* ---- Wisp transport ----
     libcurl.js has to live in its own little document. The Wisp server rejects
     the jsDelivr origin during the WebSocket handshake, and a script in a
     sandboxed srcdoc frame has an opaque origin, which the server accepts.
     The frame is invisible; requests and responses cross by postMessage. The
     relays stay as a fallback for when the socket is blocked. */

  /* Deploy wisp-server/ (see its README), then put the wss:// URL first here or
     set localStorage 'saleen.wisp'. The public relay is only a fallback. */
  var OWN_WISP = '';
  var WISP_SERVERS = (function () {
    var list = [];
    try {
      var saved = window.localStorage.getItem('saleen.wisp');
      if (saved && /^wss?:\/\//.test(saved)) list.push(saved);
    } catch (e) {}
    if (OWN_WISP) list.push(OWN_WISP);
    list.push('wss://wisp.mercurywork.shop/');
    return list;
  })();
  var LIBCURL_JS = 'https://cdn.jsdelivr.net/npm/libcurl.js@0.7.5/libcurl.js';
  var LIBCURL_WASM = 'https://cdn.jsdelivr.net/npm/libcurl.js@0.7.5/libcurl.wasm';
  var wispBoot = null;
  var wispStart = null;
  var wispReady = false;
  var wispFrame = null;
  var wispSeq = 0;
  var wispPending = {};

  function wispSource(wsUrl) {
    return [
      '<!doctype html><html><head><meta charset="utf-8"></head><body><script>',
      'var ready=false,jobs=[],started=false;',
      'function send(m){try{parent.postMessage(m,"*")}catch(e){}}',
      'function run(job){',
      '  var headers={};try{headers=job.headers||{}}catch(e){}',
      '  libcurl.fetch(job.url,{headers:headers}).then(function(res){',
      '    var read=job.kind==="text"?res.text():res.arrayBuffer();',
      '    return read.then(function(body){',
      '      try{parent.postMessage({saleen:"wisp",type:"res",id:job.id,status:res.status,ok:res.ok,body:body},"*");}',
      '      catch(e){parent.postMessage({saleen:"wisp",type:"res",id:job.id,error:"post failed"},"*");}',
      '    });',
      '  }).catch(function(e){send({saleen:"wisp",type:"res",id:job.id,error:String(e&&e.message||e)})});',
      '}',
      'window.addEventListener("message",function(e){',
      '  var d=e.data;if(!d||d.saleen!=="wisp-req")return;',
      '  var job={id:d.id,url:d.url,headers:d.headers,kind:d.kind};',
      '  if(ready)run(job);else jobs.push(job);',
      '});',
      'function boot(){',
      '  if(started)return;started=true;',
      '  var s=document.createElement("script");',
      '  s.src=' + JSON.stringify(LIBCURL_JS) + ';',
      '  s.onload=function(){',
      '    libcurl.load_wasm(' + JSON.stringify(LIBCURL_WASM) + ').then(function(){',
      '      libcurl.set_websocket(' + JSON.stringify(wsUrl) + ');',
      '      ready=true;send({saleen:"wisp",type:"ready"});',
      '      var q=jobs.slice();jobs=[];q.forEach(run);',
      '    }).catch(function(e){send({saleen:"wisp",type:"error",text:String(e&&e.message||e)})});',
      '  };',
      '  s.onerror=function(){send({saleen:"wisp",type:"error",text:"libcurl blocked"})};',
      '  document.body.appendChild(s);',
      '}',
      'boot();',
      '<\/script></body></html>'
    ].join('\n');
  }

  window.addEventListener('message', function (e) {
    var d = e.data;
    if (!d || d.saleen !== 'wisp') return;
    if (d.type === 'ready' || d.type === 'error') {
      var boot = wispBoot;
      if (d.type === 'ready') {
        if (boot) {
          window.clearTimeout(boot.timer);
          boot.resolve(true);
        }
        return;
      }
      cleanupWisp();
      if (boot) boot.reject(new Error(d.text || 'wisp failed'));
      return;
    }
    if (d.type !== 'res') return;
    var job = wispPending[d.id];
    if (!job) return;
    delete wispPending[d.id];
    window.clearTimeout(job.timer);
    if (d.error) job.reject(new Error(d.error));
    else job.resolve({ status: d.status, ok: d.ok, body: d.body });
  });

  function cleanupWisp() {
    if (wispFrame && wispFrame.parentNode) wispFrame.parentNode.removeChild(wispFrame);
    wispFrame = null;
    wispBoot = null;
  }

  function bootOne(wsUrl) {
    var frame = document.createElement('iframe');
    frame.setAttribute('sandbox', 'allow-scripts');
    frame.setAttribute('aria-hidden', 'true');
    frame.setAttribute('tabindex', '-1');
    frame.style.cssText = 'position:fixed;left:-9999px;top:0;width:2px;height:2px;border:0;opacity:0;pointer-events:none';
    frame.srcdoc = wispSource(wsUrl);
    var mount = document.getElementById('saleen-root') || document.documentElement;
    mount.appendChild(frame);
    wispFrame = frame;

    return new Promise(function (resolve, reject) {
      var timer = window.setTimeout(function () {
        reject(new Error('wisp boot timeout'));
      }, 16000);
      wispBoot = { resolve: resolve, reject: reject, timer: timer };
    });
  }

  function tryWispServer(i) {
    if (i >= WISP_SERVERS.length) return Promise.reject(new Error('no wisp server'));
    return bootOne(WISP_SERVERS[i]).catch(function () {
      cleanupWisp();
      return tryWispServer(i + 1);
    });
  }

  function bootWisp() {
    if (wispReady && wispFrame) return Promise.resolve(true);
    if (wispStart) return wispStart;
    wispStart = tryWispServer(0).then(function (ok) {
      wispReady = true;
      return ok;
    }).catch(function (err) {
      wispStart = null;
      cleanupWisp();
      throw err;
    });
    return wispStart;
  }

  function wispFetch(url, kind, headers) {
    return bootWisp().then(function () {
      return new Promise(function (resolve, reject) {
        if (!wispFrame || !wispFrame.contentWindow) {
          reject(new Error('wisp frame missing'));
          return;
        }
        var id = ++wispSeq;
        var job = { resolve: resolve, reject: reject, timer: null };
        job.timer = window.setTimeout(function () {
          delete wispPending[id];
          reject(new Error('wisp timeout'));
        }, 24000);
        wispPending[id] = job;
        try {
          wispFrame.contentWindow.postMessage({
            saleen: 'wisp-req', id: id, url: url, kind: kind,
            headers: headers || {}
          }, '*');
        } catch (e) {
          delete wispPending[id];
          window.clearTimeout(job.timer);
          reject(e);
        }
      });
    });
  }

  function wispFetchText(url, accept) {
    return wispFetch(url, 'text', {
      'user-agent': navigator.userAgent,
      'accept-language': 'en-US,en;q=0.9',
      accept: accept || 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
    }).then(function (res) {
      if (!res.ok) throw new Error('wisp HTTP ' + res.status);
      return res.body;
    });
  }

  /* Small hook for the transport probe: lets a test talk to Wisp directly. */
  window.__saleenWisp = {
    boot: bootWisp,
    fetch: wispFetch,
    frame: function () { return wispFrame; }
  };

  function withTimeout(promise, ms) {
    return new Promise(function (resolve, reject) {
      var timer = window.setTimeout(function () { reject(new Error('timeout')); }, ms);
      promise.then(function (v) { window.clearTimeout(timer); resolve(v); },
        function (e) { window.clearTimeout(timer); reject(e); });
    });
  }

  /* Search engines wrap result links in redirectors. Saleen follows the real
     target so a click does not land on a redirect page that needs scripts. */
  function unwrapLink(href, base) {
    try {
      var u = new URL(href, base);
      var host = u.hostname.replace(/^www\./, '').toLowerCase();
      if (host === 'google.com' && /^\/url\/?$/i.test(u.pathname)) {
        var q = u.searchParams.get('q') || u.searchParams.get('url');
        if (q && /^https?:\/\//i.test(q)) return q;
      }
      if (host === 'startpage.com' && /^\/sp\/do\//i.test(u.pathname)) return u.href;
      return u.href;
    } catch (e) { return ''; }
  }

  function isSearchUrl(u) {
    return String(u).indexOf(SEARCH_URL) === 0;
  }

  function queryOf(u) {
    try { return new URL(u).searchParams.get('q') || ''; } catch (e) { return ''; }
  }

  function redirectTarget(href) {
    var h = String(href || '');
    try {
      var u = new URL(h, 'https://search.brave.com/');
      var encoded = u.searchParams.get('click_url');
      if (encoded && /^https?:\/\//i.test(encoded)) return encoded;
      return u.href;
    } catch (e) { return ''; }
  }

  function parseBrave(html) {
    var doc = new DOMParser().parseFromString(html, 'text/html');
    var out = [];
    var seen = {};

    Array.prototype.forEach.call(doc.querySelectorAll('.snippet'), function (node) {
      var a = node.querySelector('a[href]');
      if (!a) return;
      var href = redirectTarget(a.getAttribute('href'));
      if (!/^https?:\/\//i.test(href)) return;

      var host = hostOf(href);
      if (/(^|\.)brave\.com$/i.test(host) || /(^|\.)brave\.com$/i.test(hostOf(a.getAttribute('href')))) return;
      if (/sponsored/i.test(node.textContent || '')) return;

      var titleEl = node.querySelector('.title') || node.querySelector('[class*="title"]');
      var title = (titleEl ? titleEl.textContent : '').replace(/\s+/g, ' ').trim();
      if (!title) title = (a.textContent || '').replace(/\s+/g, ' ').trim();
      if (!title || title.length < 4) return;

      var descEl = node.querySelector('.snippet-description, [class*="description"], .snippet-content');
      var snippet = (descEl ? descEl.textContent : '').replace(/\s+/g, ' ').trim();
      if (!snippet && node.innerText) {
        var lines = node.innerText.split(/\r?\n/).map(function (l) { return l.trim(); });
        for (var i = 0; i < lines.length; i++) {
          var line = lines[i];
          if (!line || line === title) continue;
          if (/^https?:\/\//i.test(line)) continue;
          if (line.length > 30) { snippet = line; break; }
        }
      }
      if (snippet.length > 280) snippet = snippet.slice(0, 278) + '…';
      if (seen[href]) return;
      seen[href] = true;

      out.push({ title: title.slice(0, 120), url: href, snippet: snippet.replace(/\s+/g, ' ').trim() });
    });

    return out.slice(0, 20);
  }

  function searchEndpoint(q) {
    return 'https://search.brave.com/search?q=' + encodeURIComponent(q) + '&source=web';
  }

  function fetchSearch(q) {
    if (searchCache[q]) return Promise.resolve(searchCache[q]);
    var target = searchEndpoint(q);

    /* Four transports race; the first one with real results wins. Timeouts are
       short so a dead mirror never makes a search feel broken. */
    var viaReader = function () {
      return fetchWithTimeout(JINA + target, 12000, { headers: { 'x-return-format': 'html' } })
        .then(function (res) {
          if (!res.ok) throw new Error('reader HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    var viaFast = function () {
      return fetchWithTimeout(fastUrl(target), 10000)
        .then(function (res) {
          if (!res.ok) throw new Error('proxy HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    var viaProxy = function () {
      return fetchWithTimeout(proxyUrl(target), 12000)
        .then(function (res) {
          if (!res.ok) throw new Error('proxy HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    var viaCodetabs = function () {
      return fetchWithTimeout(PROXY_ALT + encodeURIComponent(target), 11000)
        .then(function (res) {
          if (!res.ok) throw new Error('proxy HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    var viaCloudflare = function () {
      return fetchWithTimeout(cfUrl(target), 11000)
        .then(function (res) {
          if (!res.ok) throw new Error('cloudflare HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    var viaLol = function () {
      return fetchWithTimeout(lolUrl(target), 10000)
        .then(function (res) {
          if (!res.ok) throw new Error('corslol HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    var viaOrg = function () {
      return fetchWithTimeout(orgUrl(target), 12000)
        .then(function (res) {
          if (!res.ok) throw new Error('corsorg HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          var results = parseBrave(html);
          if (!results.length) throw new Error('no results');
          return results;
        });
    };

    return firstOf([viaCloudflare, viaLol, viaFast, viaOrg, viaProxy, viaCodetabs, viaReader]).then(function (results) {
      searchCache[q] = results;
      return results;
    });
  }

  function paintResults(t, results) {
    els.searchList.textContent = '';
    els.searchList.dataset.q = t.query;

    var head = document.createElement('p');
    head.className = 'search-count';
    head.textContent = results.length + ' results for “' + t.query + '” · Saleen Search';
    els.searchList.appendChild(head);

    results.forEach(function (r) {
      var a = document.createElement('a');
      a.className = 'search-result';
      a.href = r.url;
      a.addEventListener('click', function (e) {
        e.preventDefault();
        navigate(r.url);
      });

      var title = document.createElement('span');
      title.className = 'search-title';
      title.textContent = r.title;

      var host = document.createElement('span');
      host.className = 'search-url';
      host.textContent = hostOf(r.url);

      var snip = document.createElement('span');
      snip.className = 'search-snippet';
      snip.textContent = r.snippet;

      a.appendChild(host);
      a.appendChild(title);
      if (r.snippet) a.appendChild(snip);
      els.searchList.appendChild(a);
    });
  }

  function renderSearch(t) {
    var q = t.query;
    els.searchPane.hidden = false;
    els.frame.hidden = true;
    els.note.textContent = 'Saleen Search';
    els.pageLoadingText.textContent = 'Searching the web…';

    if (els.searchList.dataset.q === q && els.searchList.children.length) {
      els.pageLoading.hidden = true;
      return;
    }

    els.searchList.textContent = '';
    els.searchList.dataset.q = '';
    els.pageLoading.hidden = false;

    var token = ++searchReq;
    fetchSearch(q).then(function (results) {
      if (token !== searchReq || activeTab() !== t || t.url !== SEARCH_URL + encodeURIComponent(q)) return;
      els.pageLoading.hidden = true;
      paintResults(t, results);
    }).catch(function () {
      if (token !== searchReq || activeTab() !== t) return;
      els.pageLoading.hidden = true;
      els.searchList.textContent = '';

      var p = document.createElement('p');
      p.className = 'search-status';
      p.textContent = 'The search proxy did not answer. Saleen can still read a page if you type a link.';

      var again = document.createElement('button');
      again.type = 'button';
      again.className = 'primary-btn';
      again.textContent = 'Try again';
      again.addEventListener('click', function () {
        delete searchCache[q];
        els.searchList.dataset.q = '';
        renderSearch(t);
      });

      els.searchList.appendChild(p);
      els.searchList.appendChild(again);
    });
  }

  function rewriteCss(css, base) {
    return String(css).replace(/url\((['"]?)([^)'"]+)\1\)/gi, function (m, q, u) {
      if (/^(data:|#|about:)/i.test(u)) return m;
      var abs = absoluteUrl(u, base);
      if (!abs) return m;
      /* Secure URLs load straight from their host (much faster); only insecure
         ones need the proxy so the page stays https-clean. */
      return 'url(' + (/^https:/i.test(abs) ? abs : cfUrl(abs)) + ')';
    });
  }

  var cssCache = {};

  /* Page stylesheets are fetched through the same proxy and inlined, because a
     linked sheet inside a proxied document can silently fail and leave a site
     looking blank. Text is cheap; a broken layout is not. */
  function fetchCss(url) {
    if (cssCache[url] !== undefined) return Promise.resolve(cssCache[url]);

    var pull = function (builder) {
      return fetchWithTimeout(builder(url), 9000)
        .then(function (res) {
          if (!res.ok) throw new Error('css HTTP ' + res.status);
          return res.text();
        })
        .then(function (css) {
          var text = String(css || '');
          if (!text || text.length < 16 || text.length > 900000 || text.charAt(0) === '<') {
            throw new Error('not css');
          }
          return text;
        });
    };

    return firstOf([
      function () { return pull(cfUrl); },
      function () { return pull(lolUrl); },
      function () { return pull(fastUrl); },
      function () { return pull(proxyUrl); }
    ])
      .then(function (text) {
        cssCache[url] = text;
        return text;
      })
      .catch(function () {
        cssCache[url] = '';
        return '';
      });
  }

  var BASE_CSS = [
    '*,*::before,*::after{box-sizing:border-box}',
    'html{background:#fff;-webkit-text-size-adjust:100%;overflow-x:hidden}',
    'body{margin:0;background:#fff;color:#15171c;font:16px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;overflow-x:hidden}',
    'img,svg,video,canvas{max-width:100%;height:auto}',
    'a{color:#1a56db}',
    'pre{overflow:auto}',
    'table{border-collapse:collapse;max-width:100%}',
    '::selection{background:#cddfff;color:#000}'
  ].join('');

  /* When a site's own skin cannot be fetched, the page would otherwise show a
     huge unstyled masthead of menus. In that case the chrome is hidden and the
     article column is given a clean, readable layout instead. */
  var FALLBACK_CSS = [
    'header,nav,aside,footer,[role="banner"],[role="navigation"],[role="contentinfo"],',
    '.mw-header,.vector-header-container,.vector-sticky-header,#mw-navigation,',
    '.mw-jump-link,.mw-aria-live-region,.nav,.navbar,.site-header,.sidebar{display:none!important}',
    'main,article,#mw-content-text,.content,#content,.post,.entry-content{',
    'max-width:860px;margin:0 auto;padding:26px 22px;float:none!important;width:auto!important}',
    'h1,h2,h3{line-height:1.28;margin:1.4em 0 .5em}',
    'p,li{max-width:74ch}',
    'figure,table,.infobox,.thumb{float:none!important;margin:18px auto!important;max-width:100%!important}'
  ].join('');

  /* Conservative ad cleanup for proxied pages: scripts and frames are already
     stripped, so this only removes the leftover ad slots and tracking pixels. */
  function stripPageAds(doc) {
    var adRe = /(^|[\s_-])(ad|ads|advert|advertisement|sponsor|sponsored|promo|promoted)([\s_-]|$)/i;
    var keep = /adapter|adobe|shadow|gradient|header|download|loading|upload|radio|thread|studio|badge|read|adapt/i;
    Array.prototype.forEach.call(doc.querySelectorAll('div,section,aside,ins,span'), function (n) {
      var marker = (n.getAttribute('id') || '') + ' ' + (n.getAttribute('class') || '');
      if (!adRe.test(marker) || keep.test(marker)) return;
      if (n.parentNode) n.parentNode.removeChild(n);
    });
    Array.prototype.forEach.call(doc.querySelectorAll('img[src]'), function (n) {
      if (/doubleclick|googlesyndication|adservice|adnxs|taboola|outbrain|revcontent|mgid|criteo|pubmatic|rubiconproject|amazon-adsystem|moatads/i.test(n.getAttribute('src') || '')) {
        if (n.parentNode) n.parentNode.removeChild(n);
      }
    });
  }

  function buildPage(html, url) {
    if (!/<(html|body|div|p|article|main)\b/i.test(html)) return null;

    var doc = new DOMParser().parseFromString(html, 'text/html');
    Array.prototype.forEach.call(
      doc.querySelectorAll('script,noscript,iframe,object,embed,applet,frame,frameset,base,meta[http-equiv]'),
      function (n) { if (n.parentNode) n.parentNode.removeChild(n); }
    );
    stripPageAds(doc);

    var sheets = [];
    Array.prototype.forEach.call(doc.querySelectorAll('link[href]'), function (l) {
      var rel = (l.getAttribute('rel') || '').toLowerCase();
      if (rel.indexOf('stylesheet') < 0 || sheets.length >= 3) {
        if (l.parentNode) l.parentNode.removeChild(l);
        return;
      }
      var abs = absoluteUrl(l.getAttribute('href'), url);
      if (!abs) { if (l.parentNode) l.parentNode.removeChild(l); return; }
      sheets.push({ link: l, url: abs });
    });

    Array.prototype.forEach.call(doc.querySelectorAll('img'), function (img) {
      img.removeAttribute('srcset');
      var src = img.getAttribute('src') || img.getAttribute('data-src') || '';
      var abs = absoluteUrl(src, url);
      if (abs) {
        img.setAttribute('src', /^https:/i.test(abs) ? abs : cfUrl(abs));
        img.setAttribute('loading', 'lazy');
      } else {
        img.removeAttribute('src');
      }
    });

    Array.prototype.forEach.call(doc.querySelectorAll('[style]'), function (el) {
      el.setAttribute('style', rewriteCss(el.getAttribute('style') || '', url));
    });
    Array.prototype.forEach.call(doc.querySelectorAll('style'), function (el) {
      el.textContent = rewriteCss(el.textContent || '', url);
    });

    Array.prototype.forEach.call(doc.querySelectorAll('a[href]'), function (a) {
      var abs = unwrapLink(a.getAttribute('href'), url);
      if (abs) a.setAttribute('href', abs);
      else a.removeAttribute('href');
    });

    Array.prototype.forEach.call(doc.querySelectorAll('form'), function (f) {
      var abs = absoluteUrl(f.getAttribute('action') || url, url);
      if (abs) f.setAttribute('action', abs);
    });

    var head = doc.head || doc.documentElement;
    var base = doc.createElement('style');
    base.setAttribute('data-saleen', 'base');
    base.textContent = BASE_CSS;
    head.insertBefore(base, head.firstChild);

    /* Without a script runtime the site's own fixed-width chrome is all that is
       left. Give it a normal device viewport and then, after paint, scale the
       document down if it is still wider than the frame (the "zoomed in"
       look glitchy sites have in a small window). */
    var viewport = doc.querySelector('meta[name="viewport"]');
    if (!viewport) {
      viewport = doc.createElement('meta');
      viewport.setAttribute('name', 'viewport');
      head.insertBefore(viewport, head.firstChild);
    }
    viewport.setAttribute('content', 'width=device-width,initial-scale=1');

    return Promise.all(sheets.map(function (s) { return fetchCss(s.url); })).then(function (texts) {
      var failed = 0;
      sheets.forEach(function (s, i) {
        var css = texts[i];
        if (!css) {
          failed += 1;
          s.link.setAttribute('href', proxyUrl(s.url));
          return;
        }
        var inline = doc.createElement('style');
        inline.setAttribute('data-saleen', 'sheet');
        inline.textContent = rewriteCss(css, s.url);
        if (s.link.parentNode) s.link.parentNode.replaceChild(inline, s.link);
      });

      if (failed) {
        var fallback = doc.createElement('style');
        fallback.setAttribute('data-saleen', 'fallback');
        fallback.textContent = FALLBACK_CSS;
        head.appendChild(fallback);
      }

      var bridge = doc.createElement('script');
      bridge.textContent = [
        '(function(){',
        'function send(u){try{parent.postMessage({saleen:"nav",url:u},"*")}catch(e){}}',
        'document.addEventListener("click",function(e){',
        'var a=e.target&&e.target.closest?e.target.closest("a"):null;if(!a)return;',
        'var h=a.getAttribute("href")||"";if(!/^https?:/i.test(h))return;',
        'e.preventDefault();send(h);},true);',
        'document.addEventListener("submit",function(e){',
        'var f=e.target;if(!f||!f.action)return;e.preventDefault();',
        'var qs="";try{qs=new URLSearchParams(new FormData(f)).toString()}catch(err){}',
        'send(f.action.split("?")[0]+(qs?"?"+qs:""));},true);',
        'var over=false;',
        'function fit(){',
        'var d=document.documentElement;if(!d)return;',
        'var w=d.clientWidth||window.innerWidth;if(!w)return;',
        'var sw=d.scrollWidth||0;if(over){d.style.zoom="";over=false;sw=d.scrollWidth||0}',
        'if(sw>w+12&&w>240){var z=Math.max(.4,Math.min(1,w/sw));if(z<.995){d.style.zoom=String(z);over=true}}',
        '}',
        'window.addEventListener("resize",function(){setTimeout(fit,180)});',
        'window.addEventListener("load",function(){setTimeout(fit,120)});',
        'setTimeout(fit,500);setTimeout(fit,1800);setTimeout(fit,4000);',
        '})();'
      ].join('\n');
      (doc.body || doc.documentElement).appendChild(bridge);

      var title = (doc.title || '').replace(/\s+/g, ' ').trim();
      var text = (doc.body ? doc.body.textContent : '').replace(/\s+/g, ' ').trim();
      if (text.length < 40 && !doc.querySelector('img,video,canvas,svg')) return null;

      return { html: '<!doctype html>' + doc.documentElement.outerHTML, title: title, url: url };
    });
  }

  function fetchPage(url) {
    if (pageCache[url]) return Promise.resolve(pageCache[url]);

    var attempt = function (key, make, ms) {
      return fetchWithTimeout(make(url), ms)
        .then(function (res) {
          if (!res.ok) throw new Error(key + ' HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) {
          if (!html || html.length < 120) throw new Error(key + ' empty');
          return buildPage(html, url);
        })
        .then(function (built) {
          if (!built) throw new Error(key + ' unreadable');
          proxyHealth[key] = 0;
          return built;
        })
        .catch(function (err) {
          proxyHealth[key] = Date.now();
          throw err;
        });
    };

    /* Several proxies race and the first page that actually renders wins, so a
       slow or rate-limited host never stalls the tab. A proxy that just failed
       is skipped for a minute. */
    var race = function () {
      var tries = [];
      if (!cooling('cloudflare')) tries.push(function () { return attempt('cloudflare', cfUrl, 9000); });
      if (!cooling('corslol')) tries.push(function () { return attempt('corslol', lolUrl, 9000); });
      if (!cooling('corsfix')) tries.push(function () { return attempt('corsfix', fastUrl, 9000); });
      if (!cooling('corsorg')) tries.push(function () { return attempt('corsorg', orgUrl, 11000); });
      if (!cooling('allorigins')) tries.push(function () { return attempt('allorigins', proxyUrl, 11000); });
      if (!cooling('codetabs')) tries.push(function () { return attempt('codetabs', function (u) { return PROXY_ALT + encodeURIComponent(u); }, 11000); });
      if (!tries.length) {
        tries.push(
          function () { return attempt('cloudflare', cfUrl, 9000); },
          function () { return attempt('corsfix', fastUrl, 9000); }
        );
      }
      return firstOf(tries);
    };

    var viaReader = function () {
      return fetchWithTimeout(JINA + url, 12000, { headers: { 'x-return-format': 'html' } })
        .then(function (res) {
          if (!res.ok) throw new Error('reader HTTP ' + res.status);
          return res.text();
        })
        .then(function (html) { return buildPage(html, url); })
        .then(function (built) {
          if (!built) throw new Error('reader unreadable');
          return built;
        });
    };

    var viaWisp = function () {
      return withTimeout(wispFetchText(url), 15000)
        .then(function (html) {
          if (!html || html.length < 120) throw new Error('wisp empty');
          return buildPage(html, url);
        })
        .then(function (built) {
          if (!built) throw new Error('wisp unreadable');
          return built;
        });
    };

    return viaWisp()
      .catch(function () {
        return race()
          .catch(function () {
            /* One more shot before falling back to the reader. */
            return new Promise(function (resolve) { window.setTimeout(resolve, 350); }).then(race);
          })
          .catch(viaReader);
      })
      .then(function (built) {
        pageCache[url] = built;
        return built;
      });
  }

  function paintPage(t, built) {
    els.pageLoading.hidden = true;
    els.frame.srcdoc = built.html;
    els.frame.dataset.url = built.url;
    if (built.title && built.title !== t.title) {
      t.title = built.title.slice(0, 60);
      renderTabs();
      updateTitle();
    }
  }

  function paintPageError(url) {
    els.pageLoading.hidden = true;
    els.frame.hidden = false;
    els.note.textContent = 'Saleen · ' + hostOf(url);
    els.frame.dataset.url = url;
    els.frame.srcdoc = [
      '<!doctype html><html><head><meta charset="utf-8">',
      '<meta name="viewport" content="width=device-width,initial-scale=1">',
      '</head><body><div>',
      '<p>That page would not open.</p>',
      '<button id="again" type="button">Try again</button>',
      '</div><script>',
      'document.getElementById("again").onclick=function(){parent.postMessage({saleen:"retry"},"*");};',
      '<\/script></body></html>'
    ].join('');
  }

  function loadPage(t) {
    var url = t.url;
    els.searchPane.hidden = true;
    els.frame.hidden = false;
    els.pageLoading.hidden = false;
    els.pageLoadingText.textContent = DESKTOP ? 'Opening page…' : 'Opening through Saleen…';
    els.note.textContent = DESKTOP ? 'Desktop mode · real rendering' : 'Saleen · ' + hostOf(url);

    if (DESKTOP) {
      if (els.frame.dataset.url !== url) {
        els.frame.removeAttribute('srcdoc');
        els.frame.dataset.url = url;
        els.frame.src = url;
      }
      els.pageLoading.hidden = true;
      return;
    }

    if (pageCache[url]) { paintPage(t, pageCache[url]); return; }
    if (els.frame.dataset.url === url && els.frame.srcdoc) { els.pageLoading.hidden = true; return; }

    var token = ++pageReq;
    els.frame.removeAttribute('src');
    els.frame.dataset.url = url;
    els.frame.srcdoc = '';

    fetchPage(url).then(function (built) {
      if (token !== pageReq || activeTab() !== t || t.url !== url) return;
      paintPage(t, built);
    }).catch(function () {
      if (token !== pageReq || activeTab() !== t || t.url !== url) return;
      paintPageError(url);
    });
  }

  window.addEventListener('message', function (e) {
    var data = e.data;
    if (!data || e.source !== els.frame.contentWindow) return;

    if (data.saleen === 'retry') {
      var t = activeTab();
      if (!t || !t.url) return;
      delete pageCache[t.url];
      loadPage(t);
      return;
    }

    if (data.saleen !== 'nav' || typeof data.url !== 'string') return;
    if (!/^https?:\/\//i.test(data.url)) return;
    navigate(data.url);
  });

  function renderView() {
    var t = activeTab();
    rootNode().dataset.mode = mode;

    var hasWeb = !!(mode === 'browser' && t && t.mode === 'web' && t.url);
    var isSearch = !!(hasWeb && isSearchUrl(t.url));
    var emptyTab = mode === 'browser' && !hasWeb;
    var clockPage = mode === 'home';

    els.chrome.hidden = mode !== 'browser';
    els.newTabView.hidden = !clockPage;
    els.startView.hidden = !emptyTab;
    els.heroTyping.hidden = !(clockPage || emptyTab);
    els.webWrap.hidden = !hasWeb;
    els.aiView.hidden = mode !== 'ai';
    els.linksView.hidden = mode !== 'links';
    els.gamesView.hidden = mode !== 'games';
    var isMedia = mode === 'movies' || mode === 'tv' || mode === 'music';
    els.moviesView.hidden = !isMedia;
    if (isMedia && els.mediaTitle) els.mediaTitle.textContent = MODE_TITLES[mode];

    navItems.forEach(function (item) {
      item.setAttribute('aria-current', item.dataset.mode === mode ? 'page' : 'false');
    });

    if (mode === 'browser' && t) {
      if (hasWeb) {
        els.omni.value = isSearch ? queryOf(t.url) : t.url;

        if (isSearch) {
          renderSearch(t);
        } else {
          els.searchPane.hidden = true;
          t.reader = false;
          loadPage(t);
        }
      } else {
        els.omni.value = '';
        els.searchPane.hidden = true;
        els.pageLoading.hidden = true;
        els.frame.hidden = false;
        els.frame.dataset.url = '';
      }
      els.back.disabled = t.hi <= 0;
      els.fwd.disabled = t.hi >= t.hist.length - 1;
      els.reload.disabled = !(t.mode === 'web' && t.url);
    }

    updateTitle();
  }

  function setMode(next) {
    if (['home', 'ai', 'links', 'games', 'movies', 'tv', 'music', 'browser'].indexOf(next) < 0) next = 'home';
    var changed = next !== mode;
    /* Leaving the player stops the stream instead of letting it keep pulling
       segments behind the other tabs. */
    if (changed && next !== 'movies' && next !== 'tv' && media.item) closeMedia();
    mode = next;
    renderView();
    if (next === 'home') startTyping();
    if (next === 'movies' || next === 'tv' || next === 'music') startMovies(next);
    if (next === 'games') startGames();
    if (changed) document.dispatchEvent(new CustomEvent('saleen:mode', { detail: mode }));
  }

  function setTabUrl(t, url) {
    t.url = url;
    t.mode = 'web';
    t.kind = isSearchUrl(url) ? 'search' : 'page';
    t.query = t.kind === 'search' ? queryOf(url) : '';
    t.title = t.kind === 'search' ? t.query : hostOf(url);
    els.frame.dataset.url = '';
  }

  function navigate(url) {
    var t = activeTab();
    if (!t) t = createTab();
    t.hist = t.hist.slice(0, t.hi + 1);
    t.hist.push(url);
    t.hi = t.hist.length - 1;
    setTabUrl(t, url);
    renderTabs();
    renderView();
  }

  function goBack() {
    var t = activeTab();
    if (!t || t.hi <= 0) return;
    t.hi -= 1;
    setTabUrl(t, t.hist[t.hi]);
    renderTabs();
    renderView();
  }

  function goFwd() {
    var t = activeTab();
    if (!t || t.hi >= t.hist.length - 1) return;
    t.hi += 1;
    setTabUrl(t, t.hist[t.hi]);
    renderTabs();
    renderView();
  }

  function reload() {
    var t = activeTab();
    if (!t || t.mode !== 'web' || !t.url) return;
    delete readerCache[t.url];
    delete pageCache[t.url];
    if (isSearchUrl(t.url)) {
      delete searchCache[queryOf(t.url)];
      els.searchList.dataset.q = '';
    }
    els.frame.dataset.url = '';
    renderView();
  }

  /* ---------------- address + search ---------------- */

  function looksLikeUrl(v) {
    if (/^[a-z][a-z0-9+.-]*:\/\//i.test(v)) return true;
    if (/^(localhost|\d{1,3}(\.\d{1,3}){3})(:\d+)?([/?#]|$)/i.test(v)) return true;
    if (/\s/.test(v)) return false;
    return /^[^\s/?#:]+\.[a-z]{2,}(:\d+)?([/?#]|$)/i.test(v);
  }

  function toUrl(v) {
    if (/^[a-z][a-z0-9+.-]*:\/\//i.test(v)) return v;
    if (/^(localhost|\d{1,3}(\.\d{1,3}){3})(:\d+)?/i.test(v)) return 'http://' + v;
    return 'https://' + v;
  }

  function search(q) {
    els.omni.value = '';
    navigate(SEARCH_URL + encodeURIComponent(q));
  }

  function submit(raw) {
    var v = (raw || '').trim();
    if (!v) return;
    if (looksLikeUrl(v)) {
      var url = toUrl(v);
      if (/^https?:\/\//i.test(url) || /^file:\/\//i.test(url)) {
        els.omni.value = '';
        navigate(url);
        return;
      }
    }
    search(v);
  }

  /* ---------------- toast ---------------- */

  var toastTimer = null;
  function toast(msg) {
    els.toast.textContent = msg;
    els.toast.classList.add('show');
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function () { els.toast.classList.remove('show'); }, 2600);
  }

  /* ---------------- links ---------------- */

  var LINKS_KEY = 'saleen.links.v3';
  var myLinks = [];

  /* Every link, always present. Any that go missing are added back once, in
     order, and duplicates are dropped. */
  var KEEP_LINK = 'https://cdn.jsdelivr.net/gh/blunts294/saleen/saleen.svg';
  var SEED_LINKS = [
    { id: 'saleen-app', name: 'Saleen', url: KEEP_LINK, tag: 'app' }
  ];

  function seedLinks() {
    return SEED_LINKS.map(function (l) {
      return { id: l.id || ('l' + Math.random().toString(36).slice(2, 8)), name: l.name, url: l.url, tag: l.tag, added: Date.now() };
    });
  }

  /* One link only. Everything else that used to live on this shelf is dropped,
     so the tab always shows exactly the single live address. */
  function withSeedLinks() {
    return seedLinks();
  }

  function readMyLinks() {
    try {
      /* Older builds saved a shelf of starter links under these keys. They are
         removed once so the Links tab starts genuinely empty. */
      ['saleen.links.v1', 'saleen.links.v2'].forEach(function (k) {
        try { localStorage.removeItem(k); } catch (e) {}
      });
      var raw = localStorage.getItem(LINKS_KEY);
      if (!raw) {
        myLinks = seedLinks();
        writeMyLinks();
        return;
      }
      var before = localStorage.getItem(LINKS_KEY) || '';
      myLinks = withSeedLinks();
      if (JSON.stringify(myLinks) !== before) writeMyLinks();
    } catch (e) { myLinks = seedLinks(); }
  }

  function writeMyLinks() {
    try { localStorage.setItem(LINKS_KEY, JSON.stringify(myLinks)); } catch (e) {}
    broadcast('links');
  }

  function linkFromInput(raw) {
    var v = String(raw || '').trim();
    if (!v) return null;
    var url;
    var name;
    if (/^https?:\/\//i.test(v)) {
      url = v;
    } else if (looksLikeUrl(v)) {
      url = toUrl(v);
    } else {
      url = SEARCH_URL + encodeURIComponent(v);
      name = v;
    }
    if (!/^https?:\/\//i.test(url) && url.indexOf(SEARCH_URL) !== 0) return null;
    return { url: url, name: name || hostOf(url), added: Date.now() };
  }

  /* Links are the one thing that leaves Saleen: each opens in a real browser
     tab. Everything searched or opened from the address bar stays inside. */
  function openLink(link) {
    if (!link || !link.url) return;
    window.open(link.url, '_blank', 'noopener,noreferrer');
  }

  function makeCard(link, removable) {
    var card = document.createElement('div');
    card.className = 'link-card';

    var open = document.createElement('button');
    open.type = 'button';
    open.className = 'link-open';
    open.title = link.url;

    var ico = document.createElement('span');
    ico.className = 'link-ico';
    ico.setAttribute('aria-hidden', 'true');
    var isSearchLink = link.url.indexOf(SEARCH_URL) === 0;
    ico.textContent = isSearchLink
      ? '⌕'
      : (link.name || link.url).replace(/^www\./i, '').charAt(0).toUpperCase();

    var text = document.createElement('span');
    text.className = 'link-text';
    var name = document.createElement('span');
    name.className = 'link-name';
    name.textContent = link.name || hostOf(link.url);
    var meta = document.createElement('span');
    meta.className = 'link-host';
    var prefix = link.tag || '';
    var where = isSearchLink ? queryOf(link.url) : hostOf(link.url);
    meta.textContent = prefix ? prefix + ' · ' + where : where;
    text.appendChild(name);
    text.appendChild(meta);

    open.appendChild(ico);
    open.appendChild(text);
    open.addEventListener('click', function () { openLink(link); });
    card.appendChild(open);

    if (removable) {
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'link-del';
      del.textContent = '✕';
      del.title = 'Remove link';
      del.setAttribute('aria-label', 'Remove ' + (link.name || link.url));
      del.addEventListener('click', function () {
        myLinks = myLinks.filter(function (l) { return l.url !== link.url; });
        writeMyLinks();
        renderLinks();
        toast('Link removed');
      });
      card.appendChild(del);
    }

    return card;
  }

  function renderLinks() {
    if (!els.myLinks) return;
    els.myLinks.textContent = '';
    els.myLinksCount.textContent = String(myLinks.length);

    if (myLinks.length) {
      myLinks.forEach(function (link) { els.myLinks.appendChild(makeCard(link, false)); });
    }
  }

  /* ---------------- games (live shelf) ---------------- */

  var GAMES_KEY = 'saleen.games.v2';
  var games = [];

  function readGames() {
    try {
      var saved = JSON.parse(localStorage.getItem(GAMES_KEY) || '[]');
      if (Array.isArray(saved)) {
        games = saved.filter(function (g) {
          return g && typeof g.url === 'string' && /^(https?:\/\/|saleen:\/\/)/i.test(g.url);
        });
      }
    } catch (e) { games = []; }
  }

  function writeGames() {
    try { localStorage.setItem(GAMES_KEY, JSON.stringify(games)); } catch (e) {}
    broadcast('games');
    renderGames();
  }

  function renderGames() {
    if (!els.gamesBody) return;
    els.gamesBody.textContent = '';

    if (!games.length) {
      return;
    }

    var grid = document.createElement('div');
    grid.className = 'links-grid';
    games.forEach(function (g) { grid.appendChild(makeCard(g, false)); });
    els.gamesBody.appendChild(grid);
  }

  /* ---------------- movies + tv (catalogue, one English stream) ----------------
     CinemaOS is only used as a keyless TMDB reader now: its own player kept
     cycling through dead sources and language tracks. The posters and titles
     come from that API. Playback is not an embed any more: the provider's own
     HLS playlist is resolved and handed to a plain <video> element, with every
     non-English audio track and every subtitle track stripped out. */

  var MEDIA_API = 'https://cinemaos.in/api/tmdb';
  var MEDIA_IMG = 'https://image.tmdb.org/t/p/w342';
  var MEDIA_PLAY = 'https://vidlink.pro/movie';
  var MEDIA_PLAY_TV = 'https://vidlink.pro/tv';
  var VIX_API_MOVIE = 'https://vixsrc.to/api/movie/';
  var VIX_API_TV = 'https://vixsrc.to/api/tv/';
  var HLS_JS = 'https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js';
  var MEDIA_FILTERS = {
    movie: {
      trending: '/trending/movie/day',
      popular: '/movie/popular',
      top: '/movie/top_rated'
    },
    tv: {
      trending: '/trending/tv/day',
      popular: '/tv/popular',
      top: '/tv/top_rated'
    }
  };
  var MEDIA_CACHE = {};
  var MEDIA_MAX_PAGE = 10;
  var MEDIA_REGION = 'US';

  /* Hand-picked popular titles that are pinned to the top of the catalogue.
     TMDB ids, so the poster/title/date come from the same source as the rest. */
  var CURATED_IDS = {
    tv: [1434, 456, 1396, 2316, 66732, 60625, 2190, 1668, 1418, 48891,
      1429, 387, 246, 60574, 119051, 76479, 32726, 1433, 615, 2710],
    movie: [550, 155, 27205, 157336, 603692, 872585, 693134, 533535, 1022789, 634649,
      76600, 361743, 414906, 346698, 447365, 502356, 808, 12, 862, 597]
  };
  var CURATED_CACHE = {};

  function curatedFor(kind) {
    var ids = CURATED_IDS[kind] || [];
    if (CURATED_CACHE[kind]) return Promise.resolve(CURATED_CACHE[kind]);
    var out = [];
    var at = 0;

    function batch() {
      if (at >= ids.length) {
        CURATED_CACHE[kind] = out;
        return Promise.resolve(out);
      }
      var slice = ids.slice(at, at + 5);
      at += 5;
      return Promise.all(slice.map(function (id) {
        return mediaFetch('/' + kind + '/' + id).then(function (data) {
          if (!data || !data.id || !mediaPoster(data)) return null;
          return data;
        }).catch(function () { return null; });
      })).then(function (items) {
        items.forEach(function (item) { if (item) out.push(item); });
        return batch();
      });
    }

    return batch();
  }

  function mergeCurated(extra, list) {
    var seen = {};
    var merged = [];
    (extra || []).forEach(function (item) {
      if (seen[item.id]) return;
      seen[item.id] = 1;
      merged.push(item);
    });
    list.forEach(function (item) {
      if (seen[item.id]) return;
      seen[item.id] = 1;
      merged.push(item);
    });
    return merged;
  }
  var media = {
    kind: 'movie',
    filter: 'trending',
    provider: '',
    query: '',
    mode: 'grid',
    items: [],
    page: 1,
    maxPage: 1,
    loadingMore: false,
    item: null,
    seasons: [],
    season: 1,
    episodeNum: 1,
    source: 'vidrock',
    frame: null,
    stepTimer: 0
  };
  var mediaSearchTimer = null;
  var musicFrame = null;
  var movieProgress = 0;
  var movieTarget = 0;
  var movieTicker = null;

  function movieStep(at, to, text) {
    movieProgress = Math.max(movieProgress, at);
    movieTarget = to;
    if (els.movieFill) els.movieFill.style.width = movieProgress + '%';
    if (text && els.movieStatus) els.movieStatus.textContent = text;
  }

  function movieTickerStart() {
    window.clearInterval(movieTicker);
    movieTicker = window.setInterval(function () {
      if (movieProgress >= movieTarget - 1) return;
      movieProgress += (movieTarget - movieProgress) * 0.08;
      if (els.movieFill) els.movieFill.style.width = movieProgress + '%';
    }, 180);
  }

  function movieDone() {
    window.clearInterval(movieTicker);
    movieStep(100, 100, 'Tap play');
    window.setTimeout(function () {
      if (els.movieLoad) {
        els.movieLoad.classList.add('done');
        /* Take it out of the layout as well: a transparent panel that is still
           present can swallow taps on slow devices. */
        els.movieLoad.hidden = true;
      }
      if (els.movieWrap) els.movieWrap.hidden = false;
    }, 420);
  }

  function movieReset(text) {
    window.clearInterval(movieTicker);
    movieProgress = 0;
    movieTarget = 0;
    if (els.movieFill) els.movieFill.style.width = '0%';
    if (els.movieLoad) {
      els.movieLoad.hidden = false;
      els.movieLoad.classList.remove('done');
    }
    if (text) movieStep(6, 40, text);
    movieTickerStart();
  }

  function mediaName(item) {
    return item.title || item.name || item.original_title || item.original_name || 'Untitled';
  }

  function mediaYear(item) {
    return String(item.release_date || item.first_air_date || '').slice(0, 4);
  }

  function mediaPoster(item) {
    var path = item.poster_path || item.backdrop_path || '';
    return path ? MEDIA_IMG + path : '';
  }

  function mediaCountLabel(n) {
    if (!els.mediaSub) return;
    els.mediaSub.textContent = n ? n + (n === 1 ? ' title' : ' titles') : '';
  }

  function mediaChipsMark() {
    els.mediaChips.forEach(function (chip) {
      var f = chip.getAttribute('data-filter');
      var ok = !!(MEDIA_FILTERS[media.kind] && MEDIA_FILTERS[media.kind][f]);
      chip.hidden = !ok;
      chip.setAttribute('aria-pressed', ok && f === media.filter && !media.provider ? 'true' : 'false');
    });
    els.providerChips.forEach(function (chip) {
      var p = chip.getAttribute('data-provider') || '';
      chip.setAttribute('aria-pressed', p === media.provider ? 'true' : 'false');
    });
  }

  function mediaChrome(view) {
    var grid = view === 'grid';
    media.mode = grid ? 'grid' : 'player';
    if (els.mediaGrid) els.mediaGrid.hidden = !grid;
    if (els.mediaFilters) els.mediaFilters.hidden = !grid;
    if (els.providerFilters) els.providerFilters.hidden = !grid;
    if (els.mediaSearch) els.mediaSearch.hidden = !grid;
    /* Always leave a way out: from a movie it goes back to the list, from the
       list it goes back Home. */
    if (els.mediaBack) {
      els.mediaBack.hidden = false;
      els.mediaBack.textContent = grid ? 'Home' : 'Back';
    }
    if (grid) {
      if (els.seasonSel) { els.seasonSel.hidden = true; els.seasonSel.textContent = ''; }
      if (els.episodeSel) { els.episodeSel.hidden = true; els.episodeSel.textContent = ''; }
    }
  }

  function mediaFetch(path) {
    var url = MEDIA_API + path;
    return fetchWithTimeout(url, 14000).then(function (res) {
      if (!res.ok) throw new Error('media HTTP ' + res.status);
      return res.json();
    }).catch(function () {
      return fetchWithTimeout(cfUrl(url), 16000).then(function (res) {
        if (!res.ok) throw new Error('media HTTP ' + res.status);
        return res.json();
      });
    });
  }

  function renderMediaGrid(list, append) {
    if (!els.mediaGrid) return;
    if (!append) els.mediaGrid.textContent = '';
    var frag = document.createDocumentFragment();
    list.forEach(function (item) {
      var card = document.createElement('button');
      card.type = 'button';
      card.className = 'media-card';
      card.title = mediaName(item);

      var art = document.createElement('span');
      art.className = 'media-art';
      var src = mediaPoster(item);
      if (src) {
        var img = document.createElement('img');
        img.alt = '';
        img.loading = 'lazy';
        img.decoding = 'async';
        img.src = src;
        img.addEventListener('error', function () { img.remove(); });
        art.appendChild(img);
      }

      var info = document.createElement('span');
      info.className = 'media-info';
      var name = document.createElement('span');
      name.className = 'media-name';
      name.textContent = mediaName(item);
      var year = document.createElement('span');
      year.className = 'media-year';
      year.textContent = mediaYear(item) || (media.kind === 'tv' ? 'TV' : 'Movie');

      info.appendChild(name);
      info.appendChild(year);
      card.appendChild(art);
      card.appendChild(info);
      card.addEventListener('click', function () { openMedia(item); });
      frag.appendChild(card);
    });
    els.mediaGrid.appendChild(frag);
    els.mediaGrid.hidden = false;
    mediaCountLabel(els.mediaGrid.querySelectorAll('.media-card').length);
  }

  /* ---------------- paging: the whole catalogue, not just page 1 ---------------- */

  function mediaPagePath(page) {
    var base;
    if (media.query) {
      base = '/search/' + (media.kind === 'tv' ? 'tv' : 'movie') +
        '?query=' + encodeURIComponent(media.query) + '&include_adult=false';
    } else if (media.provider) {
      base = '/discover/' + (media.kind === 'tv' ? 'tv' : 'movie') +
        '?with_watch_providers=' + encodeURIComponent(media.provider) +
        '&watch_region=' + MEDIA_REGION +
        '&sort_by=popularity.desc&vote_count.gte=100&include_adult=false';
    } else {
      base = MEDIA_FILTERS[media.kind][media.filter];
    }
    if (page <= 1) return base;
    return base + (base.indexOf('?') >= 0 ? '&' : '?') + 'page=' + page;
  }

  /* The catalogue is a popularity feed, but TMDB still slips brand-new or
     straight-to-video titles with a handful of votes into it. Those are the
     cards that looked like filler, so they are dropped unless the user asked
     for them by name. */
  function mediaTooObscure(item) {
    var votes = Number(item.vote_count) || 0;
    var pop = Number(item.popularity) || 0;
    if (votes >= 60) return false;
    return pop < 60;
  }

  function mediaParse(data, page) {
    var list = ((data && data.results) || []).filter(function (item) {
      if (!item || !item.id || !mediaPoster(item)) return false;
      if (!media.query && mediaTooObscure(item)) return false;
      return true;
    });
    var pages = Number(data && data.total_pages) || page;
    media.maxPage = Math.max(1, Math.min(pages, MEDIA_MAX_PAGE));
    return list;
  }

  function mediaRemember() {
    var key = media.kind + ':' + (media.query ? 'q:' + media.query : (media.provider ? 'p:' + media.provider : media.filter));
    MEDIA_CACHE[key] = {
      items: media.items,
      page: media.page,
      maxPage: media.maxPage,
      query: media.query,
      filter: media.filter,
      provider: media.provider
    };
  }

  function mediaSettled() {
    window.clearInterval(movieTicker);
    movieStep(100, 100, 'Ready');
    if (els.movieLoad) els.movieLoad.classList.add('done');
  }

  function mediaLoad(filter, force) {
    if (!els.mediaGrid) return Promise.resolve();
    var kind = media.kind;
    var key = kind + ':' + filter;
    media.filter = filter;
    media.query = '';
    media.page = 1;
    media.maxPage = 1;
    media.loadingMore = false;
    mediaChipsMark();
    movieReset(kind === 'tv' ? 'Loading shows' : 'Loading movies');

    var cached = MEDIA_CACHE[key];
    if (!force && cached) {
      media.items = cached.items;
      media.page = cached.page;
      media.maxPage = cached.maxPage;
      renderMediaGrid(media.items);
      mediaSettled();
      return Promise.resolve();
    }

    if (els.mediaGrid) els.mediaGrid.hidden = true;
    return mediaFetch(MEDIA_FILTERS[kind][filter]).then(function (data) {
      var list = mediaParse(data, 1);
      if (!list.length) throw new Error('empty list');
      return curatedFor(kind).then(function (extra) {
        media.items = mergeCurated(extra, list);
        mediaRemember();
        renderMediaGrid(media.items);
        mediaSettled();
      });
    }).catch(function () {
      window.clearInterval(movieTicker);
      if (els.movieStatus) els.movieStatus.textContent = 'Could not load the list. Try another tab.';
      if (els.movieFill) els.movieFill.style.width = '0%';
      if (els.movieLoad) {
        els.movieLoad.hidden = false;
        els.movieLoad.classList.remove('done');
      }
    });
  }

  /* Appends the next page in place. Uses the same path builder as page 1 so
     search results page too, and de-dupes ids TMDB repeats across pages. */
  function mediaMore() {
    if (media.mode !== 'grid' || media.loadingMore) return Promise.resolve();
    if (media.page >= media.maxPage) return Promise.resolve();
    media.loadingMore = true;
    var want = media.page + 1;
    if (els.mediaSub) els.mediaSub.textContent = 'Loading more…';

    return mediaFetch(mediaPagePath(want)).then(function (data) {
      if (want !== media.page + 1) return;
      var list = mediaParse(data, want);
      var seen = {};
      media.items.forEach(function (i) { seen[i.id] = 1; });
      var fresh = list.filter(function (i) { return !seen[i.id]; });
      media.page = want;
      if (fresh.length) {
        media.items = media.items.concat(fresh);
        renderMediaGrid(fresh, true);
      } else {
        mediaCountLabel(els.mediaGrid.querySelectorAll('.media-card').length);
      }
      mediaRemember();
    }).catch(function () {
      /* keep whatever is on screen; the scroll handler can retry */
      mediaCountLabel(els.mediaGrid.querySelectorAll('.media-card').length);
    }).then(function () {
      media.loadingMore = false;
    });
  }

  function openMedia(item) {
    media.item = item;
    media.seasons = [];
    media.season = 1;
    if (els.mediaTitle) els.mediaTitle.textContent = mediaName(item);
    if (els.mediaSub) {
      var bits = [];
      var year = mediaYear(item);
      if (year) bits.push(year);
      if (item.vote_average) bits.push(Number(item.vote_average).toFixed(1) + '/10');
      bits.push('English');
      els.mediaSub.textContent = bits.join(' · ');
    }
    mediaChrome('player');
    if (media.kind === 'tv') loadSeasons(item);
    else playMedia(1, 1);
  }

  function loadSeasons(item) {
    movieReset('Loading episodes');
    mediaFetch('/tv/' + item.id).then(function (data) {
      if (!media.item || media.item.id !== item.id) return;
      var seasons = ((data && data.seasons) || []).filter(function (s) {
        return s && s.season_number > 0 && s.episode_count > 0;
      });
      if (!seasons.length) throw new Error('no seasons');
      media.seasons = seasons;
      if (els.seasonSel) {
        els.seasonSel.textContent = '';
        seasons.forEach(function (s) {
          var opt = document.createElement('option');
          opt.value = String(s.season_number);
          opt.textContent = 'Season ' + s.season_number + ' (' + s.episode_count + ')';
          els.seasonSel.appendChild(opt);
        });
        els.seasonSel.hidden = false;
      }
      selectSeason(seasons[0].season_number, true);
    }).catch(function () {
      if (!media.item || media.item.id !== item.id) return;
      playMedia(1, 1);
    });
  }

  function selectSeason(number, autoplay) {
    media.season = number;
    if (els.seasonSel) { els.seasonSel.value = String(number); els.seasonSel.hidden = false; }
    if (els.episodeSel) { els.episodeSel.textContent = ''; els.episodeSel.hidden = true; }
    var id = media.item ? media.item.id : 0;
    mediaFetch('/tv/' + id + '/season/' + number).then(function (data) {
      if (!media.item || media.item.id !== id) return;
      var eps = ((data && data.episodes) || []).filter(function (e) { return e && e.episode_number; });
      if (!eps.length) throw new Error('no episodes');
      if (els.episodeSel) {
        eps.forEach(function (e) {
          var opt = document.createElement('option');
          opt.value = String(e.episode_number);
          opt.textContent = 'E' + e.episode_number + (e.name ? ' · ' + e.name : '');
          els.episodeSel.appendChild(opt);
        });
        els.episodeSel.hidden = false;
      }
      if (autoplay) playMedia(number, eps[0].episode_number);
    }).catch(function () {
      if (autoplay) playMedia(number, 1);
    });
  }

  /* ---- resolving the stream (no iframe) ---- */

  function loadScriptOnce(src, marker) {
    return new Promise(function (resolve, reject) {
      if (marker && window[marker]) { resolve(window[marker]); return; }
      var s = document.createElement('script');
      s.src = src;
      s.async = true;
      s.onload = function () {
        if (marker && !window[marker]) { reject(new Error('script empty')); return; }
        resolve(marker ? window[marker] : true);
      };
      s.onerror = function () { reject(new Error('script blocked')); };
      /* This app also runs as an SVG document, where document.head is null.
         The XHTML wrapper inside the foreignObject hosts scripts fine. */
      var mount = document.getElementById('saleen-root') ||
        document.head || document.documentElement;
      mount.appendChild(s);
    });
  }

  var hlsBoot = null;
  var hlsPlayer = null;
  var hlsBlob = null;
  var playerVideo = null;
  var VIX_CACHE = {};

  function loadHls() {
    if (window.Hls) return Promise.resolve(window.Hls);
    if (!hlsBoot) {
      hlsBoot = loadScriptOnce(HLS_JS, 'Hls').catch(function (err) {
        hlsBoot = null;
        throw err;
      });
    }
    return hlsBoot;
  }

  /* vixsrc's metadata endpoints are Cloudflare-protected and send no CORS
     headers, so the small JSON/HTML lookups go through public readers. The
     playlist itself is CORS-open, so the video segments come straight from
     the CDN and stream at full speed. */
  function vixText(url, accept) {
    var tries = [
      function (u) { return 'https://corsproxy.org/?' + encodeURIComponent(u); },
      function (u) { return 'https://api.codetabs.com/v1/proxy/?quest=' + encodeURIComponent(u); },
      function (u) { return 'https://api.allorigins.win/raw?url=' + encodeURIComponent(u); },
      function (u) { return cfUrl(u); },
      function (u) { return fastUrl(u); }
    ].map(function (make) {
      return function () {
        return fetchWithTimeout(make(url), 12000, { headers: { accept: accept || '*/*' } })
          .then(function (res) {
            if (!res.ok) throw new Error('meta ' + res.status);
            return res.text();
          });
      };
    });
    return firstOf(tries);
  }

  function vixPlaylistUrl(kind, id, season, episode) {
    var key = kind + ':' + id + ':' + season + ':' + episode;
    if (VIX_CACHE[key]) return VIX_CACHE[key];

    var api = kind === 'tv'
      ? VIX_API_TV + id + '/' + season + '/' + episode
      : VIX_API_MOVIE + id;

    var job = vixText(api, 'application/json').then(function (txt) {
      var data;
      try { data = JSON.parse(txt); } catch (e) { throw new Error('bad api'); }
      if (!data || !data.src) throw new Error('no source');
      return /^https?:/i.test(data.src) ? data.src : 'https://vixsrc.to' + data.src;
    }).then(function (embed) {
      return vixText(embed, 'text/html').then(function (html) {
        var token = (html.match(/'token':\s*'([^']+)'/) || [])[1] || '';
        var expires = (html.match(/'expires':\s*'([^']+)'/) || [])[1] || '';
        var playlist = (html.match(/url:\s*'([^']+)'/) || [])[1];
        if (!playlist) throw new Error('no playlist');
        return playlist + '?token=' + encodeURIComponent(token) +
          '&expires=' + encodeURIComponent(expires) + '&h=1&lang=en';
      });
    });

    VIX_CACHE[key] = job;
    job.catch(function () { delete VIX_CACHE[key]; });
    return job;
  }

  /* Keeps only the English audio rendition and drops every subtitle track, so
     the player has nothing to switch to. */
  function englishOnlyPlaylist(text) {
    var audio = '';
    var out = [];
    String(text || '').split(/\r?\n/).forEach(function (line) {
      if (/^#EXT-X-MEDIA:TYPE=SUBTITLES/i.test(line)) return;
      if (/^#EXT-X-MEDIA:TYPE=AUDIO/i.test(line)) {
        if (!audio && /LANGUAGE="eng"/i.test(line)) audio = line;
        return;
      }
      if (/^#EXT-X-STREAM-INF/i.test(line)) line = line.replace(/,SUBTITLES="[^"]*"/i, '');
      out.push(line);
    });
    if (audio) {
      var at = 0;
      while (at < out.length && !/^#EXT-X-STREAM-INF/i.test(out[at])) at += 1;
      out.splice(at, 0, audio);
    }
    return out.join('\n');
  }

  /* ---- vidrock: a CORS-open metadata endpoint that returns the real HLS
     playlist, encrypted with a key that ships in its own bundle. Decrypting it
     in the page means no relay, no iframe and no third party in the path. Its
     segments are MPEG-TS wrapped in a tiny PNG shell (a filter dodge on their
     side), so a custom hls.js loader peels the shell off before demuxing. */

  var VIDROCK_API = 'https://vidrock.net/api/';
  var VIDROCK_KEY = '7f3e9c2a8b5d1f4e6a9c3b7d2e5f8a1c4b6d9e2f5a8c1b4d7e9f2a5c8b1d4e7f';
  var vidrockKeyJob = null;

  function hexBytes(hex) {
    var out = new Uint8Array(hex.length / 2);
    for (var i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
    return out;
  }

  function b64urlBytes(text) {
    var s = String(text || '').replace(/-/g, '+').replace(/_/g, '/');
    var pad = s.length % 4;
    if (pad === 2) s += '==';
    else if (pad === 3) s += '=';
    else if (pad === 1) throw new Error('bad base64');
    var bin = atob(s);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function vidrockKey() {
    if (!window.crypto || !window.crypto.subtle) return Promise.reject(new Error('no webcrypto'));
    if (!vidrockKeyJob) {
      vidrockKeyJob = window.crypto.subtle.importKey(
        'raw', hexBytes(VIDROCK_KEY), { name: 'AES-GCM' }, false, ['decrypt']
      ).catch(function (err) {
        vidrockKeyJob = null;
        throw err;
      });
    }
    return vidrockKeyJob;
  }

  function vidrockDecrypt(key, payload) {
    var raw = b64urlBytes(payload);
    if (raw.length < 28) return Promise.reject(new Error('short ciphertext'));
    return window.crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: raw.slice(0, 12) }, key, raw.slice(12)
    ).then(function (plain) {
      return new TextDecoder().decode(plain);
    });
  }

  /* Only English, HLS sources are considered. Nova is normally the English
     one; the loop just means a renamed slot still works. */
  function vidrockStream(kind, id, season, episode) {
    var path = kind === 'tv'
      ? 'tv/' + id + '/' + season + '/' + episode
      : 'movie/' + id;
    return fetchWithTimeout(VIDROCK_API + path, 9000, { headers: { accept: 'application/json' } })
      .then(function (res) {
        if (!res.ok) throw new Error('vidrock ' + res.status);
        return res.json();
      })
      .then(function (map) {
        var names = Object.keys(map || {}).filter(function (name) {
          var src = map[name];
          return src && src.url && /^hls$/i.test(src.type || '') &&
            /english/i.test(src.language || '');
        });
        if (!names.length) throw new Error('no english source');
        return vidrockKey().then(function (key) {
          /* Every mirror is decrypted up front. Some of them answer 403 to a
             plain fetch (they want a vidrock referer), so the player walks the
             whole list instead of trusting the first name. */
          return Promise.all(names.map(function (name) {
            return vidrockDecrypt(key, map[name].url).then(function (url) {
              if (!/^https?:\/\//i.test(url)) return null;
              return { url: url, name: name };
            }).catch(function () { return null; });
          })).then(function (list) {
            var out = list.filter(Boolean);
            if (!out.length) throw new Error('no url');
            return out;
          });
        });
      });
  }

  /* Strips the PNG wrapper: 64 bytes of fake 1x1 PNG in front, sometimes a
     trailer behind. Returns the TS payload on a 188-byte packet boundary. */
  function tsPayload(buffer) {
    var u = new Uint8Array(buffer);
    if (u[0] !== 0x89 || u[1] !== 0x50) return buffer;
    var start = -1;
    for (var i = 0; i < 600 && i + 188 * 8 < u.length; i++) {
      var ok = true;
      for (var k = 0; k < 8; k++) {
        if (u[i + 188 * k] !== 0x47) { ok = false; break; }
      }
      if (ok) { start = i; break; }
    }
    if (start < 0) return buffer;
    var keep = Math.floor((u.length - start) / 188) * 188;
    return u.slice(start, start + keep).buffer;
  }

  function pngLoader(Hls) {
    var Base = Hls.DefaultConfig.loader;
    return class PngLoader extends Base {
      load(context, config, callbacks) {
        var done = callbacks.onSuccess;
        callbacks.onSuccess = function (response, stats, ctx, net) {
          try {
            if (response && response.data instanceof ArrayBuffer) {
              response.data = tsPayload(response.data);
            }
          } catch (e) { }
          done(response, stats, ctx, net);
        };
        super.load(context, config, callbacks);
      }
    };
  }

  /* The stream hosts reject a browser request no matter which referer is sent:
     they fingerprint the presence of an Origin header. libcurl on the other
     side of the Wisp socket is a plain HTTP client, so playlists and segments
     can be pulled with the referer the CDN expects. */
  function wispLoader(Hls) {
    var Base = Hls.DefaultConfig.loader;
    return class WispLoader extends Base {
      constructor(config) {
        super(config);
        this.aborted = false;
        this.timer = null;
      }
      load(context, config, callbacks) {
        var self = this;
        var url = context.url;
        var wantsText = context.type === 'manifest' || context.type === 'level' ||
          context.type === 'audioTrack' || context.type === 'subtitleTrack' ||
          /\.m3u8(?:[?#]|$)/i.test(url);
        var stats = self.stats = {
          trequest: performance.now(), tfirst: 0, tload: 0,
          loaded: 0, total: 0, bwEstimate: 0, aborted: false
        };

        self.aborted = false;
        self.callbacks = callbacks;

        var fail = function (err) {
          if (self.aborted) return;
          self.aborted = true;
          window.clearTimeout(self.timer);
          callbacks.onError({
            code: 0,
            text: String(err && err.message ? err.message : err)
          }, context, null, stats);
        };

        self.timer = window.setTimeout(function () { fail(new Error('wisp timeout')); }, 32000);

        wispFetch(url, wantsText ? 'text' : 'array', {
          'user-agent': navigator.userAgent,
          referer: 'https://vidrock.net/',
          origin: 'https://vidrock.net',
          accept: '*/*'
        }).then(function (res) {
          if (!res || self.aborted) return null;
          if (!res.ok) throw new Error('HTTP ' + res.status);
          if (stats.tfirst === 0) stats.tfirst = performance.now();
          window.clearTimeout(self.timer);
          var data = res.body;
          if (wantsText) {
            var text = String(data);
            /* hls.js asks for the master and every variant through here, so
               the English-only edit happens before it ever parses them. */
            if (/^#EXTM3U/.test(text)) text = englishOnlyPlaylist(text);
            data = text;
          } else {
            data = tsPayload(data);
          }
          stats.tload = performance.now();
          stats.loaded = stats.total = data.byteLength || data.length || 0;
          callbacks.onSuccess({ url: url, data: data }, stats, context, res);
        }).catch(fail);
      }
      abort() {
        this.aborted = true;
        window.clearTimeout(this.timer);
      }
      destroy() {
        this.aborted = true;
        window.clearTimeout(this.timer);
      }
    };
  }

  function stopPlayer() {
    window.clearTimeout(media.stepTimer);
    if (hlsPlayer) {
      try { hlsPlayer.destroy(); } catch (e) { }
      hlsPlayer = null;
    }
    if (hlsBlob) { try { URL.revokeObjectURL(hlsBlob); } catch (e) { } hlsBlob = null; }
    if (playerVideo && playerVideo.parentNode) playerVideo.parentNode.removeChild(playerVideo);
    playerVideo = null;
    if (media.frame && media.frame.parentNode) media.frame.parentNode.removeChild(media.frame);
    media.frame = null;
  }

  function embedFallback(src, note) {
    stopPlayer();
    if (!els.movieWrap) return;
    if (note) movieStep(100, 100, note);
    var frame = document.createElement('iframe');
    frame.title = media.item ? mediaName(media.item) : 'Player';
    frame.allow = 'autoplay; fullscreen; encrypted-media; picture-in-picture';
    frame.setAttribute('allowfullscreen', '');
    frame.setAttribute('referrerpolicy', 'origin');
    els.movieWrap.appendChild(frame);
    media.frame = frame;
    frame.src = src;

    movieDone();
  }

  /* Playback is handed to a provider's own player. Two providers are wired in:
     Vidsrc is the default and Vidrock is the fallback, and the small chip in the
     corner of the player switches between them without leaving the page. */
  var MEDIA_SOURCES = [
    {
      id: 'vidsrc',
      label: 'Vidsrc',
      src: function (item, kind, s, e) {
        return 'https://vidsrc.sh/embed/' + (kind === 'tv'
          ? 'tv/' + item.id + '/' + s + '/' + e + '/'
          : 'movie/' + item.id + '/');
      }
    },
    {
      id: 'vidrock',
      label: 'Vidrock',
      src: function (item, kind, s, e) {
        return 'https://vidrock.net/' + (kind === 'tv'
          ? 'tv/' + item.id + '/' + s + '/' + e
          : 'movie/' + item.id);
      }
    }
  ];

  function mediaSourceById(id) {
    for (var i = 0; i < MEDIA_SOURCES.length; i++) {
      if (MEDIA_SOURCES[i].id === id) return MEDIA_SOURCES[i];
    }
    return MEDIA_SOURCES[0];
  }

  function playMedia(season, episode, useSource) {
    if (!els.movieWrap || !media.item) return;
    var item = media.item;
    var s = Math.max(1, season || 1);
    var e = Math.max(1, episode || 1);
    if (useSource) media.source = useSource;
    media.season = s;
    media.episodeNum = e;

    stopPlayer();
    els.movieWrap.textContent = '';
    els.movieWrap.hidden = false;
    movieReset('Starting the player');

    var first = mediaSourceById(media.source);
    var order = [first].concat(MEDIA_SOURCES.filter(function (p) { return p.id !== first.id; }));
    var index = 0;

    function addSourceChip(provider) {
      var chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'movie-src';
      chip.title = 'Switch source';
      chip.textContent = provider.label;
      chip.addEventListener('click', function () {
        var next = (index % order.length);
        playMedia(s, e, order[next].id);
      });
      els.movieWrap.appendChild(chip);
    }

    function mount() {
      if (index >= order.length) {
        movieStep(100, 100, 'Tap play');
        movieDone();
        return;
      }
      var provider = order[index++];
      media.source = provider.id;
      els.movieWrap.textContent = '';

      var frame = document.createElement('iframe');
      frame.title = mediaName(item);
      frame.allow = 'autoplay; fullscreen; encrypted-media; picture-in-picture';
      frame.setAttribute('allowfullscreen', '');
      frame.src = provider.src(item, media.kind, s, e);
      els.movieWrap.appendChild(frame);
      media.frame = frame;
      media.video = null;

      var settled = false;
      var fallback = window.setTimeout(function () {
        if (settled) return;
        settled = true;
        mount();
      }, 10000);

      frame.addEventListener('load', function () {
        window.clearTimeout(fallback);
        if (settled) return;
        settled = true;
        movieStep(100, 100, 'Playing');
        movieDone();
        addSourceChip(provider);
      });
    }

    mount();
  }

  function closeMedia() {
    stopPlayer();
    if (els.movieWrap) { els.movieWrap.textContent = ''; els.movieWrap.hidden = true; }
    media.item = null;
    window.clearInterval(movieTicker);
    if (els.movieLoad) els.movieLoad.classList.add('done');
    mediaChrome('grid');
    if (els.mediaTitle) els.mediaTitle.textContent = media.kind === 'tv' ? 'TV' : 'Movies';
    mediaCountLabel(media.items.length);
  }

  function doMediaSearch(q) {
    if (!q) { mediaLoad(media.filter, false); return; }
    media.query = q;
    media.page = 1;
    media.maxPage = 1;
    media.loadingMore = false;
    if (els.mediaGrid) els.mediaGrid.hidden = true;
    movieReset('Searching');
    mediaFetch(mediaPagePath(1)).then(function (data) {
      if (media.query !== q) return;
      var list = mediaParse(data, 1);
      media.items = list;
      mediaRemember();
      renderMediaGrid(list);
      mediaSettled();
      if (!list.length && els.mediaSub) els.mediaSub.textContent = 'No matches';
    }).catch(function () {
      window.clearInterval(movieTicker);
      if (els.movieStatus) els.movieStatus.textContent = 'Search failed. Try again.';
    });
  }

  function startMusic() {
    if (!els.movieWrap || !els.movieLoad) return;
    if (media.frame && media.frame.parentNode) media.frame.parentNode.removeChild(media.frame);
    media.frame = null;
    media.item = null;
    mediaChrome('player');
    if (els.mediaFilters) els.mediaFilters.hidden = true;
    if (els.mediaSearch) els.mediaSearch.hidden = true;
    if (els.mediaBack) els.mediaBack.hidden = true;
    if (els.mediaGrid) els.mediaGrid.hidden = true;
    if (els.mediaTitle) els.mediaTitle.textContent = 'Music';
    if (els.mediaSub) els.mediaSub.textContent = '';
    if (musicFrame && musicFrame.parentNode) return;

    els.movieWrap.textContent = '';
    els.movieWrap.hidden = false;
    movieReset('Loading music');
    movieStep(30, 82, 'Loading music');

    musicFrame = document.createElement('iframe');
    musicFrame.title = 'Music';
    musicFrame.allow = 'autoplay; fullscreen; encrypted-media; picture-in-picture';
    musicFrame.setAttribute('allowfullscreen', '');
    els.movieWrap.appendChild(musicFrame);
    musicFrame.addEventListener('load', function () {
      movieStep(92, 100, 'Ready');
      window.setTimeout(movieDone, 300);
    });
    window.setTimeout(movieDone, 15000);
    musicFrame.src = 'https://cinemaos.in/music';
  }

  function startMovies(kind) {
    if (kind === 'music') { startMusic(); return; }
    if (!els.mediaGrid || !els.movieWrap) return;

    if (musicFrame) {
      if (musicFrame.parentNode) musicFrame.parentNode.removeChild(musicFrame);
      musicFrame = null;
    }

    var next = kind === 'tv' ? 'tv' : 'movie';
    if (media.kind !== next) {
      MEDIA_CACHE = {};
      media.items = [];
      media.filter = 'trending';
      media.provider = '';
      media.query = '';
      media.page = 1;
      media.maxPage = 1;
      media.loadingMore = false;
      if (els.mediaSearch) {
        els.mediaSearch.value = '';
        els.mediaSearch.placeholder = next === 'tv' ? 'Search shows' : 'Search movies';
      }
    }
    media.kind = next;

    if (media.frame && media.frame.parentNode) media.frame.parentNode.removeChild(media.frame);
    media.frame = null;
    media.item = null;
    if (els.movieWrap) { els.movieWrap.textContent = ''; els.movieWrap.hidden = true; }
    mediaChrome('grid');
    if (els.mediaTitle) els.mediaTitle.textContent = MODE_TITLES[next === 'tv' ? 'tv' : 'movies'];
    mediaChipsMark();

    if (media.items.length) {
      renderMediaGrid(media.items);
      if (els.movieLoad) els.movieLoad.classList.add('done');
      return;
    }
    mediaLoad(media.filter, false);
  }

  function mediaInit() {
    els.mediaChips.forEach(function (chip) {
      chip.addEventListener('click', function () {
        var f = chip.getAttribute('data-filter');
        if (!MEDIA_FILTERS[media.kind] || !MEDIA_FILTERS[media.kind][f]) return;
        if (els.mediaSearch) els.mediaSearch.value = '';
        media.provider = '';
        mediaLoad(f, false);
      });
    });
    els.providerChips.forEach(function (chip) {
      chip.addEventListener('click', function () {
        var p = chip.getAttribute('data-provider') || '';
        if (els.mediaSearch) els.mediaSearch.value = '';
        media.provider = p;
        media.query = '';
        mediaLoad(p ? 'popular' : media.filter, false);
      });
    });
    if (els.mediaSearch) {
      els.mediaSearch.addEventListener('input', function () {
        var q = els.mediaSearch.value.trim();
        window.clearTimeout(mediaSearchTimer);
        mediaSearchTimer = window.setTimeout(function () { doMediaSearch(q); }, 350);
      });
    }
    if (els.mediaBack) els.mediaBack.addEventListener('click', function () {
      if (media.mode === 'player') closeMedia();
      else setMode('home');
    });

    /* Infinite scroll: fetch the next catalogue page before the user hits the
       bottom, so the grid keeps growing instead of stopping at 20 titles. */
    if (els.mediaGrid) {
      els.mediaGrid.addEventListener('scroll', function () {
        if (media.mode !== 'grid' || media.loadingMore) return;
        if (media.page >= media.maxPage) return;
        var box = els.mediaGrid;
        if (box.scrollTop + box.clientHeight >= box.scrollHeight - 800) mediaMore();
      }, { passive: true });
    }
    if (els.seasonSel) {
      els.seasonSel.addEventListener('change', function () {
        selectSeason(Number(els.seasonSel.value) || 1, true);
      });
    }
    if (els.episodeSel) {
      els.episodeSel.addEventListener('change', function () {
        playMedia(media.season, Number(els.episodeSel.value) || 1);
      });
    }
  }

  mediaInit();

  /* ---------------- games (GN Math catalogue, without the blocked host) ---------------- */

  /* gn-math.com itself is often filtered and jsDelivr's /gh/gn-math paths are
     blocked, so the catalogue and the game files are pulled from places that
     stay reachable: raw GitHub (plus a proxy fallback), the npm mirror, and
     an image resizer for the covers. */
  var GAMES_HTML_BASE = 'https://raw.githubusercontent.com/gn-math/html/main/';
  var GAMES_NPM_BASE = 'https://cdn.jsdelivr.net/npm/gn-math.github.io-main@1.0.5/html-main/';
  var GAMES_COVER_BASE = 'https://raw.githubusercontent.com/gn-math/covers/main/';
  var GAMES_CATALOGS = [
    'https://raw.githubusercontent.com/gn-math/assets/main/zones.json',
    'https://cdn.jsdelivr.net/npm/gn-math.github.io-main@1.0.5/zones.json'
  ];
  var GAMES_CACHE_KEY = 'saleen.games.catalog.v4';
  var GAMES_CACHE_MS = 6 * 60 * 60 * 1000;
  /* Titles that loaded the frame but never became playable in the sweep. */
  var GAME_BLOCK_IDS = { 10: 1, 198: 1, 368: 1 };
  var GAME_BLOCK_NAMES = /^(slope( 2)?|temple run 2|drive mad)$/i;
  var gameCatalog = null;
  var gameFrame = null;

  /* Covers: the resize CDN first (a few KB instead of ~100KB), then the raw
     file, then another GitHub mirror. If all three fail the card keeps its
     gradient and shows the game's initial, so the grid never looks broken. */
  var GAME_COVER_SOURCES = [
    function (id) { return 'https://wsrv.nl/?url=raw.githubusercontent.com/gn-math/covers/main/' + id + '.png&w=320&h=200&fit=cover&output=webp&q=80'; },
    function (id) { return GAMES_COVER_BASE + id + '.png'; },
    function (id) { return 'https://cdn.statically.io/gh/gn-math/covers/main/' + id + '.png'; }
  ];

  function gameCover(img, id) {
    var step = 0;
    img.addEventListener('error', function () {
      step += 1;
      if (step >= GAME_COVER_SOURCES.length) { img.remove(); return; }
      img.src = GAME_COVER_SOURCES[step](id);
    });
    img.src = GAME_COVER_SOURCES[0](id);
  }

  function readGameCache() {
    try {
      var saved = JSON.parse(localStorage.getItem(GAMES_CACHE_KEY) || 'null');
      if (saved && Array.isArray(saved.list) && saved.list.length && Date.now() - saved.at < GAMES_CACHE_MS) {
        return saved.list;
      }
    } catch (e) {}
    return null;
  }

  function saveGameCache(list) {
    try { localStorage.setItem(GAMES_CACHE_KEY, JSON.stringify({ at: Date.now(), list: list })); } catch (e) {}
  }

  /* One source at a time, best first. A race would let the stale npm mirror win
     and its games point at asset files that do not exist. */
  function tryEach(factories) {
    return factories.reduce(function (chain, make) {
      return chain.catch(function () { return make(); });
    }, Promise.reject(new Error('no sources')));
  }

  /* School filters answer with their own HTML page instead of an error, which
     would otherwise look like a game and get painted into the frame. */
  function looksBlocked(html) {
    var head = String(html || '').slice(0, 3000).toLowerCase();
    if (head.indexOf('<html') < 0) return false;
    return /securly|fortiguard|lightspeed systems|goguardian|iboss|content blocked|access denied|web filter|this site is blocked|site is blocked/.test(head);
  }

  function stripGameAds(html) {
    return html
      .replace(/<script[^>]*(?:googletagmanager|google-analytics|adsbygoogle|pagead2|fundingchoices|doubleclick|adservice)[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<ins[^>]*class=["'][^"']*adsbygoogle[^"']*["'][^>]*>[\s\S]*?<\/ins>/gi, '')
      .replace(/<iframe[^>]*(?:googlesyndication|doubleclick|adservice)[^>]*>[\s\S]*?<\/iframe>/gi, '');
  }

  function fetchCatalog(url) {
    return fetchWithTimeout(url, 16000).then(function (res) {
      if (!res.ok) throw new Error('catalog HTTP ' + res.status);
      return res.json();
    }).then(function (list) {
      if (!Array.isArray(list)) throw new Error('bad catalogue');
      var playable = list.filter(function (g) {
        if (!g || !(g.id >= 0) || !g.name || typeof g.url !== 'string' || !/\.html$/.test(g.url)) return false;
        if (GAME_BLOCK_IDS[g.id]) return false;
        if (GAME_BLOCK_NAMES.test(String(g.name).trim())) return false;
        return true;
      });
      if (playable.length < 20) throw new Error('catalogue too small');
      return playable;
    });
  }

  function loadGameCatalog() {
    var cached = readGameCache();
    if (cached) return Promise.resolve(cached);
    var tries = [function () { return fetchCatalog(GAMES_CATALOGS[0]); }];
    tries.push(function () { return fetchCatalog(cfUrl(GAMES_CATALOGS[0])); });
    tries.push(function () { return fetchCatalog('https://cdn.statically.io/gh/gn-math/assets/main/zones.json'); });
    tries.push(function () { return fetchCatalog('https://rawcdn.githack.com/gn-math/assets/main/zones.json'); });
    tries.push(function () { return fetchCatalog(GAMES_CATALOGS[1]); });
    return tryEach(tries).then(function (list) {
      saveGameCache(list);
      return list;
    });
  }

  function gameCountLabel(shown) {
    if (!els.gamesSub) return;
    var total = gameCatalog ? gameCatalog.length : 0;
    if (!total) { els.gamesSub.textContent = ''; return; }
    els.gamesSub.textContent = shown === total ? total + ' games' : shown + ' of ' + total + ' games';
  }

  function gameEmptyNote(show) {
    var note = $('#gameEmpty');
    if (!note && show && els.gameGrid) {
      note = document.createElement('p');
      note.id = 'gameEmpty';
      note.className = 'game-empty';
      note.textContent = 'No games match that search.';
      els.gameGrid.appendChild(note);
    }
    if (note) note.hidden = !show;
  }

  function renderGameGrid(list) {
    if (!els.gameGrid) return;
    els.gameGrid.textContent = '';
    var frag = document.createDocumentFragment();
    list.forEach(function (g) {
      var card = document.createElement('button');
      card.type = 'button';
      card.className = 'game-card';
      card.title = g.name;
      card.setAttribute('data-name', String(g.name).toLowerCase());

      var art = document.createElement('span');
      art.className = 'game-art';
      var initial = document.createElement('span');
      initial.className = 'game-initial';
      initial.textContent = String(g.name).charAt(0).toUpperCase();

      var img = document.createElement('img');
      img.alt = '';
      img.loading = 'lazy';
      img.decoding = 'async';
      gameCover(img, g.id);

      var label = document.createElement('span');
      label.className = 'game-name';
      label.textContent = g.name;

      art.appendChild(initial);
      art.appendChild(img);
      card.appendChild(art);
      card.appendChild(label);
      card.addEventListener('click', function () { openGame(g); });
      frag.appendChild(card);
    });
    els.gameGrid.appendChild(frag);
    gameEmptyNote(false);
    gameCountLabel(list.length);
    els.gameGrid.hidden = false;
  }

  function openGame(g) {
    if (!els.gameWrap) return;
    if (els.gamesTitle) els.gamesTitle.textContent = g.name;
    if (els.gamesSub) els.gamesSub.textContent = '';
    if (els.gameBack) els.gameBack.hidden = false;
    if (els.gameSearch) els.gameSearch.hidden = true;
    if (els.gameGrid) els.gameGrid.hidden = true;
    els.gameWrap.textContent = '';
    els.gameWrap.hidden = false;
    if (els.gameLoad) {
      els.gameLoad.hidden = false;
      els.gameLoad.classList.remove('done');
    }
    if (els.gameStatus) els.gameStatus.textContent = 'Loading ' + g.name;
    if (els.gameFill) els.gameFill.style.width = '20%';

    var file = g.url.split('/').pop();
    var sources = [
      GAMES_HTML_BASE + file,
      cfUrl(GAMES_HTML_BASE + file),
      'https://cdn.statically.io/gh/gn-math/html/main/' + file,
      'https://rawcdn.githack.com/gn-math/html/main/' + file,
      GAMES_NPM_BASE + file
    ];

    var pull = sources.map(function (src) {
      return function () {
        return fetchWithTimeout(src, 16000).then(function (res) {
          if (!res.ok) throw new Error('game HTTP ' + res.status);
          return res.text();
        }).then(function (html) {
          if (!html || html.length < 120 || html.indexOf('<') < 0) throw new Error('not a game page');
          if (looksBlocked(html)) throw new Error('blocked page');
          return stripGameAds(html);
        });
      };
    });

    tryEach(pull).then(function (html) {
      if (!els.gameWrap || (els.gameGrid && !els.gameGrid.hidden)) return;
      gameFrame = document.createElement('iframe');
      gameFrame.title = g.name;
      gameFrame.allow = 'autoplay; fullscreen; encrypted-media; picture-in-picture; gamepad';
      gameFrame.setAttribute('allowfullscreen', '');
      els.gameWrap.appendChild(gameFrame);
      if (els.gameFill) els.gameFill.style.width = '85%';
      gameFrame.addEventListener('load', function () {
        if (els.gameFill) els.gameFill.style.width = '100%';
        window.setTimeout(function () {
          if (els.gameLoad) els.gameLoad.classList.add('done');
        }, 250);
      });
      gameFrame.srcdoc = html;
    }).catch(function () {
      if (els.gameFill) els.gameFill.style.width = '100%';
      if (els.gameStatus) els.gameStatus.textContent = 'That game could not load. Tap Back and try another.';
      if (els.gameLoad) {
        els.gameLoad.hidden = false;
        els.gameLoad.classList.remove('done');
      }
    });
  }

  function closeGame() {
    if (gameFrame && gameFrame.parentNode) gameFrame.parentNode.removeChild(gameFrame);
    gameFrame = null;
    if (els.gameWrap) {
      els.gameWrap.textContent = '';
      els.gameWrap.hidden = true;
    }
    if (els.gameGrid) els.gameGrid.hidden = false;
    if (els.gameBack) els.gameBack.hidden = true;
    if (els.gameSearch) els.gameSearch.hidden = false;
    if (els.gamesTitle) els.gamesTitle.textContent = 'Games';
    gameCountLabel(gameCatalog ? gameCatalog.length : 0);
    if (els.gameLoad) els.gameLoad.classList.add('done');
  }

  function filterGames() {
    var q = els.gameSearch ? els.gameSearch.value.trim().toLowerCase() : '';
    var cards = els.gameGrid ? els.gameGrid.querySelectorAll('.game-card') : [];
    var shown = 0;
    Array.prototype.forEach.call(cards, function (card) {
      var hit = !q || (card.getAttribute('data-name') || '').indexOf(q) >= 0;
      card.hidden = !hit;
      if (hit) shown += 1;
    });
    gameEmptyNote(shown === 0);
    gameCountLabel(shown);
  }

  function startGames() {
    if (!els.gameGrid || !els.gameWrap) return;
    if (gameCatalog) return;
    if (els.gameLoad) {
      els.gameLoad.hidden = false;
      els.gameLoad.classList.remove('done');
    }
    if (els.gameStatus) els.gameStatus.textContent = 'Loading games';
    if (els.gameFill) els.gameFill.style.width = '12%';

    loadGameCatalog().then(function (list) {
      gameCatalog = list;
      if (els.gameFill) els.gameFill.style.width = '100%';
      renderGameGrid(list);
      if (els.gameLoad) els.gameLoad.classList.add('done');
    }).catch(function () {
      if (els.gameStatus) els.gameStatus.textContent = 'Games could not load. Tap Games again to retry.';
      if (els.gameFill) els.gameFill.style.width = '0%';
      if (els.gameLoad) {
        els.gameLoad.hidden = false;
        els.gameLoad.classList.remove('done');
      }
    });
  }

  /* ---------------- live sync ---------------- */

  var channel = null;
  try { channel = new BroadcastChannel('saleen-live'); } catch (e) { channel = null; }

  function broadcast(topic) {
    if (channel) {
      try { channel.postMessage({ topic: topic, at: Date.now() }); } catch (e) {}
    }
    document.dispatchEvent(new CustomEvent('saleen:live', { detail: topic }));
  }

  function onLive(topic) {
    if (topic === 'links') { readMyLinks(); renderLinks(); }
    else if (topic === 'games') { readGames(); renderGames(); }
  }

  if (channel) channel.addEventListener('message', function (e) {
    if (e.data && e.data.topic) onLive(e.data.topic);
  });

  window.addEventListener('storage', function (e) {
    if (e.key === LINKS_KEY) onLive('links');
    else if (e.key === GAMES_KEY) onLive('games');
  });

  document.addEventListener('saleen:live', function (e) { onLive(e.detail); });

  /* ---------------- events ---------------- */

  els.newTabBtn.addEventListener('click', function () {
    if (mode !== 'browser') setMode('browser');
    createTab();
    els.omni.focus();
  });

  navItems.forEach(function (item) {
    item.addEventListener('click', function () { setMode(item.dataset.mode); });
  });


  if (els.gameSearch) els.gameSearch.addEventListener('input', filterGames);
  if (els.gameBack) els.gameBack.addEventListener('click', closeGame);

  Array.prototype.forEach.call(document.querySelectorAll('.hero-app'), function (btn) {
    btn.addEventListener('click', function () {
      var url = btn.getAttribute('data-open');
      if (!url) return;
      setMode('browser');
      navigate(url);
    });
  });

  if (els.heroSearch) {
    els.heroSearch.addEventListener('submit', function (e) {
      e.preventDefault();
      var v = els.heroInput ? els.heroInput.value.trim() : '';
      if (!v) { if (els.heroInput) els.heroInput.blur(); return; }
      els.heroInput.value = '';
      setMode('browser');
      submit(v);
    });
  }

  els.omniForm.addEventListener('submit', function (e) {
    e.preventDefault();
    submit(els.omni.value);
  });

  els.back.addEventListener('click', goBack);
  els.fwd.addEventListener('click', goFwd);
  els.reload.addEventListener('click', reload);

  window.addEventListener('resize', function () {
    if (REDUCED) {
      sizeScene();
      if (settings.wallpaper !== 'plain') paintScene();
      return;
    }
    if (!bubbles.length) return;
    sizeScene();
  });

  /* ---------------- init ---------------- */

  load();
  sanitize();
  sizeScene();
  apply();
  var deepTab = (/[?&]tab=([a-z]+)/i.exec(location.search || '') || [])[1];
  mode = deepTab && MODE_TITLES[deepTab] ? deepTab : 'home';
  renderView();
  if (mode === 'games') startGames();
  if (mode === 'movies' || mode === 'tv' || mode === 'music') startMovies(mode);
  readMyLinks();
  renderLinks();
  readGames();
  renderGames();
  updateClock();
  window.setInterval(updateClock, 5000);
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) {
      if (playerVideo && !playerVideo.paused) playerVideo.pause();
      return;
    }
    updateClock();
    if (mode === 'home') startTyping();
  });

  /* Ask before the page is closed or navigated away from, so an accidental
     close (or something trying to kick you off the page) can be cancelled. */
  window.addEventListener('beforeunload', function (e) {
    e.preventDefault();
    e.returnValue = '';
    return '';
  });
  startTyping();
  els.omni.focus();

  /* The play.xhtml wrapper listens for this so it can tell a real boot from a
     block page and move on to the next mirror instead of sitting on an error. */
  try {
    if (window.parent && window.parent !== window) {
      window.parent.postMessage('saleen:ready', '*');
    }
  } catch (e) { }

  window.Saleen = {
    toast: toast,
    setMode: setMode,
    search: search,
    navigate: navigate,
    getSettings: function () { return settings; },
    getGames: function () { return games.slice(); },
    setGames: function (list) { games = Array.isArray(list) ? list : []; writeGames(); },
    addGame: function (game) { games.unshift(game); writeGames(); }
  };
})();


(function () {
  'use strict';

  var CHAIN = [
    { base: 'https://api.llm7.io/v1', model: 'gpt-oss:20b' },
    { base: 'https://api.llm7.io/v1', model: 'mistral-Nemo-Instruct-2407' },
    { base: 'https://api.llm7.io/v1', model: 'nemotron-3-nano:30b' },
    { base: 'https://text.pollinations.ai/openai', model: 'openai' }
  ];
  var messages = [];
  var busy = false;
  var reqId = 0;

  var el = {
    log: document.getElementById('aiLog'),
    form: document.getElementById('aiForm'),
    input: document.getElementById('aiInput'),
    clear: document.getElementById('aiClear')
  };

  try {
    ['saleen.ai.v1', 'saleen.ai.v2', 'saleen.ai.v3'].forEach(function (k) {
      localStorage.removeItem(k);
    });
  } catch (e) {}

  function endpointOf(base) {
    var b = (base || '').replace(/\/+$/, '');
    if (!b) return '';
    if (/\/chat\/completions$/.test(b)) return b;
    if (/\/v1$/.test(b)) return b + '/chat/completions';
    return b;
  }

  function autosize() {
    el.input.style.height = 'auto';
    el.input.style.height = Math.min(el.input.scrollHeight, 140) + 'px';
  }

  function bubble(role, text) {
    var d = document.createElement('div');
    d.className = 'msg ' + role;
    d.appendChild(document.createTextNode(text));
    if (role === 'err') {
      var again = document.createElement('button');
      again.type = 'button';
      again.className = 'ghost-btn msg-retry';
      again.textContent = 'Retry';
      again.addEventListener('click', retry);
      d.appendChild(again);
    }
    return d;
  }

  function drawLog() {
    el.log.textContent = '';
    messages.forEach(function (m) {
      el.log.appendChild(bubble(m.role === 'error' ? 'err' : m.role === 'user' ? 'user' : 'bot', m.content));
    });
    if (busy) el.log.appendChild(bubble('typing', 'Thinking…'));
    el.log.scrollTop = el.log.scrollHeight;
  }

  function friendlyError(err) {
    var msg = (err && err.message) ? err.message : 'Request failed.';
    if (err && err.name === 'AbortError') {
      return 'The model took too long to answer. Try again.';
    }
    if (/failed to fetch|networkerror|load failed|network request failed/i.test(msg)) {
      return 'Could not reach a model. Check your connection and try again.';
    }
    return msg;
  }

  function requestOne(attempt, history, signal) {
    var payload = {
      model: attempt.model,
      messages: [{ role: 'system', content: 'You are Saleen, a concise, friendly assistant inside a small browser. Reply in plain text.' }].concat(history)
    };

    return fetch(endpointOf(attempt.base), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: signal
    })
      .then(function (res) {
        return res.text().then(function (body) { return { ok: res.ok, status: res.status, body: body }; });
      })
      .then(function (r) {
        var data = null;
        var parsed = false;
        try { data = JSON.parse(r.body); parsed = true; } catch (e) {}
        if (!r.ok) {
          var msg = 'HTTP ' + r.status;
          if (data && data.error) {
            msg = typeof data.error === 'string' ? data.error : (data.error.message || JSON.stringify(data.error));
          } else if (r.body) {
            msg = r.body.slice(0, 240);
          }
          throw new Error(msg);
        }
        var content = '';
        if (data && data.choices && data.choices[0]) {
          content = data.choices[0].message ? data.choices[0].message.content : data.choices[0].text;
        }
        if (!content && parsed && typeof data === 'string') content = data;
        if (!content && !parsed) content = r.body;
        if (Array.isArray(content)) {
          content = content.map(function (p) { return p && p.text ? p.text : ''; }).join('');
        }
        if (!content) throw new Error('The model returned an empty reply.');
        return String(content);
      });
  }

  function respond() {
    var my = ++reqId;
    busy = true;
    drawLog();

    var history = messages.filter(function (m) {
      return m.role === 'user' || m.role === 'assistant';
    }).slice(-16).map(function (m) {
      return { role: m.role, content: m.content };
    });

    var ctrl = window.AbortController ? new AbortController() : null;
    var timer = ctrl ? window.setTimeout(function () { ctrl.abort(); }, 25000) : null;
    var lastErr = null;
    var i = 0;

    function next() {
      if (i >= CHAIN.length) return Promise.reject(lastErr || new Error('Request failed.'));
      if (ctrl && ctrl.signal.aborted) return Promise.reject(lastErr || new Error('Aborted'));
      var attempt = CHAIN[i++];
      return requestOne(attempt, history, ctrl ? ctrl.signal : undefined).catch(function (err) {
        lastErr = err;
        if (ctrl && ctrl.signal.aborted) return Promise.reject(err);
        return next();
      });
    }

    next()
      .then(function (content) {
        if (my !== reqId) return;
        messages.push({ role: 'assistant', content: content });
      })
      .catch(function (err) {
        if (my !== reqId) return;
        messages.push({ role: 'error', content: friendlyError(err) });
      })
      .then(function () {
        if (timer) window.clearTimeout(timer);
        if (my !== reqId) return;
        busy = false;
        drawLog();
        var root = document.body || document.getElementById('saleen-root');
        if (root && root.dataset.mode === 'ai') el.input.focus();
      });
  }

  /* Anything about the school filter gets the same short answer instead of a
     model request (which is also what keeps the tab working). */
  var BLOCKED = /securly|securley|secur[il]y|securly\.com|go ?guardian/i;

  function send() {
    var text = el.input.value.trim();
    if (!text || busy) return;
    el.input.value = '';
    autosize();
    messages.push({ role: 'user', content: text });

    if (BLOCKED.test(text)) {
      messages.push({ role: 'assistant', content: 'no bro \uD83D\uDE2D' });
      drawLog();
      el.input.focus();
      return;
    }

    respond();
  }

  function retry() {
    if (busy) return;
    while (messages.length && messages[messages.length - 1].role === 'error') messages.pop();
    if (!messages.length) return;

    var lastUser = null;
    for (var i = messages.length - 1; i >= 0; i -= 1) {
      if (messages[i].role === 'user') { lastUser = messages[i]; break; }
    }
    if (lastUser && BLOCKED.test(lastUser.content)) {
      messages.push({ role: 'assistant', content: 'no bro \uD83D\uDE2D' });
      drawLog();
      return;
    }

    respond();
  }

  el.form.addEventListener('submit', function (e) {
    e.preventDefault();
    send();
  });

  el.input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  });

  el.input.addEventListener('input', autosize);

  el.clear.addEventListener('click', function () {
    reqId += 1;
    busy = false;
    messages = [];
    drawLog();
    el.input.focus();
  });

  document.addEventListener('saleen:mode', function (e) {
    if (e.detail === 'ai') {
      window.setTimeout(function () { el.input.focus(); }, 30);
    }
  });

  drawLog();
})();

